LZ.data.tracks=LZ.data.tracks||{},LZ.data.tracks.b1=[{id:"b1u1",title:"Present simple or continuous",part:"Grammar · Present tenses",color:"blue",icon:"star",tips:["Present simple: habits, facts and timetables – I go, she goes.","Present continuous: now, around now, or just for a while – I'm reading.","State verbs (know, like, want, need, understand) don't usually take -ing."],lessons:[{id:"b1u1l1",title:"Every day or right now?",items:[{t:"mc",s:"My brother ___ football every weekend.",o:["plays","is playing","play","playing"],a:0,x:"Every weekend is a habit → present simple, with -s for he/she/it."},{t:"mc",s:"Be quiet! The baby ___.",o:["sleeps","is sleeping","sleep","has slept"],a:1,x:"Be quiet! means it's happening now → present continuous."},{t:"type",s:"She ___ (not like) spicy food.",a:["doesn't like","does not like"],hint:"Put the verb in the right form",x:"Negative present simple with she: doesn't + base form."},{t:"mc",s:"What ___ you usually do on Sundays?",o:["are","do","does","is"],a:1,x:"A question about a habit with you: do you + base form."},{t:"spot",s:"She don't work on Mondays.",wrong:1,fix:"doesn't",x:"he/she/it → doesn't: She doesn't work on Mondays."},{t:"tiles",pre:"Right now, my parents",post:"a film.",tiles:["are","watching","watch","is"],a:["are","watching"],x:"Right now → present continuous: are + -ing."},{t:"mc",s:"The train ___ at 7.45 tomorrow morning.",o:["leaves","is leaving","leave","left"],a:0,x:"Timetables use the present simple, even for the future."},{t:"match",pairs:[["always","a habit"],["at the moment","now"],["these days","around now"],["every year","a routine"]],x:"Time words that go with the simple or the continuous."}]},{id:"b1u1l2",title:"Habits, states and changes",items:[{t:"mc",s:"I ___ what you mean.",o:["understand","am understanding","understanding","understands"],a:0,x:"understand is a state verb – no -ing."},{t:"type",s:"___ (you / wait) for the bus?",a:["are you waiting"],hint:"Ask about now",x:"A question in the present continuous: Are you + -ing?"},{t:"mc",s:"Prices ___ higher and higher this year.",o:["get","are getting","gets","got"],a:1,x:"A change happening around now → present continuous."},{t:"spot",s:"My dad work in a hospital.",wrong:2,fix:"works",x:"he/she/it + -s: My dad works in a hospital."},{t:"mc",s:"How often ___ your grandparents?",o:["do you visit","are you visiting","you visit","visit you"],a:0,x:"How often asks about a habit → do you + base form."},{t:"tiles",pre:"I",post:"to work this week because my car is broken.",tiles:["am","walking","walk","going"],a:["am","walking"],x:"Just for a while (this week) → present continuous."},{t:"type",s:"Water ___ (boil) at 100 degrees.",a:["boils"],hint:"A scientific fact",x:"Facts → present simple, with -s for it."},{t:"mc",s:"Listen! Someone ___ at the door.",o:["knocks","is knocking","knock","has knocked"],a:1,x:"Listen! means right now → present continuous."}]}]},{id:"b1u2",title:"Past simple or continuous",part:"Grammar · Past tenses",color:"pink",icon:"pen",tips:["Past simple for finished actions: we went, did you go?, I didn't go.","Past continuous for an action in progress: I was reading when…","Learn the irregular verbs – they come up in every paper."],lessons:[{id:"b1u2l1",title:"What happened?",items:[{t:"mc",s:"We ___ to the beach last Saturday.",o:["go","went","were going","have gone"],a:1,x:"A finished time (last Saturday) → past simple."},{t:"type",s:"I ___ (not see) Tom at the party.",a:["didn't see","did not see"],hint:"Past simple negative",x:"didn't + base form."},{t:"mc",s:"___ you enjoy the film?",o:["Did","Were","Do","Was"],a:0,x:"A past simple question: Did + subject + base form."},{t:"type",s:"She ___ (buy) a new jacket yesterday.",a:["bought"],hint:"An irregular past form",x:"buy → bought."},{t:"spot",s:"Last year we goed to Italy on holiday.",wrong:3,fix:"went",x:"go is irregular: went."},{t:"match",pairs:[["take","took"],["write","wrote"],["catch","caught"],["begin","began"]],x:"Irregular past forms."},{t:"mc",s:"When I was a child, I ___ in a small village.",o:["live","lived","am living","have lived"],a:1,x:"A finished situation in the past → past simple."},{t:"tiles",pre:"How",post:"home last night?",tiles:["did","you","get","got","were"],a:["did","you","get"],x:"Did + subject + base form: How did you get home?"}]},{id:"b1u2l2",title:"While it was happening",items:[{t:"mc",s:"I ___ a shower when the phone rang.",o:["had","was having","have","am having"],a:1,x:"The longer action in progress → past continuous; the short one (rang) → past simple."},{t:"mc",s:"While we were walking home, it ___ to rain.",o:["started","was starting","starts","has started"],a:0,x:"The action that interrupts → past simple."},{t:"type",s:"What ___ (you / do) at 8 o'clock last night?",a:["were you doing"],hint:"An action in progress",x:"In progress at a past time → past continuous: were you doing."},{t:"spot",s:"When I arrived, my friends were eat pizza.",wrong:6,fix:"eating",x:"Past continuous: were + -ing."},{t:"mc",s:"I ___ TV when I heard a strange noise.",o:["watched","was watching","watch","am watching"],a:1,x:"The background action in progress → past continuous."},{t:"tiles",pre:"She",post:"for the bus when she fell.",tiles:["was","running","ran","is"],a:["was","running"],x:"Past continuous for the action in progress."},{t:"type",s:"They ___ (not listen) when the teacher explained the homework.",a:["weren't listening","were not listening"],hint:"Past continuous negative",x:"weren't + -ing."},{t:"mc",s:"___ it raining when you left?",o:["Did","Was","Were","Is"],a:1,x:"A past continuous question with it: Was it + -ing?"}]}]},{id:"b1u3",title:"Present perfect",part:"Grammar · Present perfect",color:"green",icon:"calendar",tips:["have/has + past participle: I've seen, she has eaten.","For experiences (ever, never) and recent news (just, already, yet).","for + a period (for two years), since + a starting point (since 2020)."],lessons:[{id:"b1u3l1",title:"Ever, never, just",items:[{t:"mc",s:"Have you ever ___ to London?",o:["be","been","went","go"],a:1,x:"been = visited and come back: Have you ever been to…?"},{t:"mc",s:"I've never ___ sushi.",o:["eat","ate","eaten","eating"],a:2,x:"have + past participle: eaten."},{t:"type",s:"She's just ___ (finish) her homework.",a:["finished"],hint:"Past participle",x:"just + present perfect for something very recent."},{t:"mc",s:"We ___ this film three times.",o:["saw","have seen","see","are seeing"],a:1,x:"Experience up to now, no finished time → present perfect."},{t:"spot",s:"Have you ever went to a rock concert?",wrong:3,fix:"been",x:"The present perfect needs the past participle: been."},{t:"match",pairs:[["write","written"],["speak","spoken"],["fly","flown"],["break","broken"]],x:"Irregular past participles."},{t:"tiles",pre:"Oh no, I",post:"my keys!",tiles:["have","lost","lose","had"],a:["have","lost"],x:"Present perfect: a past action with a result now – no keys."},{t:"mc",s:"___ you seen my phone anywhere?",o:["Did","Have","Has","Are"],a:1,x:"Present perfect question with you: Have you + past participle?"}]},{id:"b1u3l2",title:"Yet, already, for and since",items:[{t:"mc",s:"Have you finished your project ___?",o:["already","yet","just","since"],a:1,x:"yet goes at the end of questions and negatives."},{t:"mc",s:"I've ___ bought the tickets, so we don't need to queue.",o:["yet","already","ever","since"],a:1,x:"already = sooner than expected; it goes before the past participle."},{t:"mc",s:"We've lived here ___ 2019.",o:["for","since","from","ago"],a:1,x:"since + a point in time."},{t:"mc",s:"She's worked at the café ___ six months.",o:["since","for","ago","during"],a:1,x:"for + a length of time."},{t:"type",s:"I haven't had breakfast ___.",a:["yet"],hint:"One word for negatives",x:"yet at the end of a negative sentence."},{t:"spot",s:"I have known her since three years.",wrong:4,fix:"for",x:"for + a period of time: for three years."},{t:"mc",s:"I ___ my homework yesterday evening.",o:["have done","did","have did","done"],a:1,x:"yesterday evening is a finished time → past simple, not present perfect."},{t:"tiles",pre:"How long",post:"each other?",tiles:["have","you","known","did","knew"],a:["have","you","known"],x:"How long + present perfect for something that started in the past and goes on."}]}]},{id:"b1u4",title:"Talking about the future",part:"Grammar · Future forms",color:"amber",icon:"target",tips:["will: decisions made now, promises, predictions with I think.","going to: plans you've already made, and predictions from what you can see.","Present continuous for fixed arrangements; present simple for timetables."],lessons:[{id:"b1u4l1",title:"Will or going to?",items:[{t:"mc",s:"Look at those clouds! It ___ rain.",o:["will","is going to","is","going"],a:1,x:"A prediction from what you can see now → going to."},{t:"mc",s:"I'm thirsty. – Wait, I ___ get you some water.",o:["will","am","going","was"],a:0,x:"A decision made at the moment of speaking → will."},{t:"mc",s:"We ___ visit my cousins next weekend – we planned it last month.",o:["will","are going to","go","went"],a:1,x:"A plan decided before → going to."},{t:"type",s:"I think it ___ (be) sunny tomorrow.",a:["will be","'ll be"],hint:"An opinion about the future",x:"I think + will."},{t:"spot",s:"Don't worry, I will to help you tomorrow.",wrong:4,fix:"(no 'to')",x:"will + base form, without to: I will help you."},{t:"match",pairs:[["Too hot?","I'll open a window."],["I've bought paint.","I'm going to paint."],["Look at the sky!","It's going to rain."],["I promise","I won't tell anyone."]],x:"Decisions and promises (will), plans and evidence (going to)."},{t:"tiles",pre:"What",post:"this summer?",tiles:["are","you","going","to","do","will","doing"],a:["are","you","going","to","do"],x:"Asking about plans → be going to."},{t:"mc",s:"I promise I ___ tell anyone your secret.",o:["won't","am not going","don't","not will"],a:0,x:"Promises → will / won't."}]},{id:"b1u4l2",title:"Plans, timetables and arrangements",items:[{t:"mc",s:"I ___ the dentist at 4 pm tomorrow – it's in my diary.",o:["see","am seeing","saw","have seen"],a:1,x:"A fixed arrangement with a time → present continuous."},{t:"mc",s:"The film ___ at 8.15, so let's meet at 8.",o:["starts","is starting","started","has started"],a:0,x:"Timetables (films, trains, lessons) → present simple."},{t:"type",s:"What time ___ (the train / leave)?",a:["does the train leave"],hint:"A timetable question",x:"Timetables → present simple: What time does the train leave?"},{t:"mc",s:"Maybe I ___ study medicine at university.",o:["will","am","going","shall to"],a:0,x:"maybe / probably + will for an uncertain future."},{t:"spot",s:"We are meet our friends at the café tonight.",wrong:2,fix:"meeting",x:"An arrangement → present continuous: are meeting."},{t:"mc",s:"___ I open the window? It's hot in here.",o:["Will","Shall","Am","Do"],a:1,x:"Shall I…? = an offer."},{t:"type",s:"I'm sure you ___ (pass) your exam.",a:["will pass","'ll pass"],hint:"A prediction with I'm sure",x:"I'm sure + will."},{t:"tiles",pre:"We",post:"a party on Saturday – do you want to come?",tiles:["are","having","have","had"],a:["are","having"],x:"An arrangement → present continuous."}]}]},{id:"b1u5",title:"Comparing things",part:"Grammar · Comparatives",color:"violet",icon:"chart",tips:["Short adjectives: -er / the -est (cheaper, the cheapest).","Long adjectives: more / the most (more expensive, the most expensive).","as … as means the same; not as … as means less."],lessons:[{id:"b1u5l1",title:"Bigger, better, more interesting",items:[{t:"mc",s:"My new phone is ___ than my old one.",o:["fast","faster","fastest","more fast"],a:1,x:"Short adjective + -er + than."},{t:"mc",s:"This is the ___ book I've ever read.",o:["good","better","best","most good"],a:2,x:"good → better → the best."},{t:"type",s:"Maths is ___ (difficult) than history for me.",a:["more difficult"],hint:"A long adjective",x:"Long adjectives: more + adjective + than."},{t:"mc",s:"Today is ___ than yesterday.",o:["hot","hotter","hoter","more hot"],a:1,x:"One vowel + one consonant: double it – hot → hotter."},{t:"spot",s:"Tokyo is more bigger than London.",wrong:2,fix:"(no 'more')",x:"Don't use more with -er: Tokyo is bigger than London."},{t:"match",pairs:[["bad","worse"],["far","further"],["happy","happier"],["little","less"]],x:"Irregular comparatives and spelling changes."},{t:"mc",s:"It's the ___ expensive restaurant in town.",o:["more","most","much","very"],a:1,x:"Superlative of long adjectives: the most + adjective."},{t:"tiles",pre:"She is",post:"in our class.",tiles:["the","tallest","girl","taller","most"],a:["the","tallest","girl"],x:"the + -est for the top of a group."}]},{id:"b1u5l2",title:"As … as, too and enough",items:[{t:"mc",s:"My sister is as tall ___ me.",o:["than","as","like","that"],a:1,x:"as + adjective + as = the same."},{t:"mc",s:"This bag isn't ___ enough for all my books.",o:["big","bigger","too big","biggest"],a:0,x:"adjective + enough."},{t:"mc",s:"The coffee is ___ hot to drink.",o:["too","enough","so","very much"],a:0,x:"too + adjective = more than you want."},{t:"type",s:"He isn't as clever ___ he thinks.",a:["as"],hint:"One word",x:"not as … as."},{t:"mc",s:"The weather today is ___ worse than yesterday.",o:["much","very","more","most"],a:0,x:"much / a lot / far + comparative makes it stronger."},{t:"spot",s:"You aren't enough old to drive.",wrong:2,fix:"old enough",x:"enough goes after the adjective: old enough."},{t:"tiles",pre:"The test was",post:"I expected.",tiles:["easier","than","easy","that"],a:["easier","than"],x:"Comparative + than."},{t:"mc",s:"It's the ___ day of the year.",o:["shortest","most short","shorter","more short"],a:0,x:"Short adjective superlative: the shortest."}]}]},{id:"b1u6",title:"Must, have to, should, can",part:"Grammar · Modal verbs",color:"teal",icon:"bolt",tips:["Modals take the base form: can swim, must go – never to.","mustn't = not allowed; don't have to = not necessary.","should for advice; could for polite requests and past ability."],lessons:[{id:"b1u6l1",title:"Rules and advice",items:[{t:"mc",s:"You ___ wear a seatbelt in the car. It's the law.",o:["must","should","can","might"],a:0,x:"must = a strong rule or obligation."},{t:"mc",s:"You look tired. You ___ go to bed earlier.",o:["must","should","have","can't"],a:1,x:"should = advice."},{t:"mc",s:"You ___ bring food – lunch is included.",o:["mustn't","don't have to","can't","shouldn't"],a:1,x:"don't have to = it isn't necessary."},{t:"mc",s:"You ___ use your phone during the exam. It's forbidden.",o:["don't have to","mustn't","needn't","shouldn't"],a:1,x:"mustn't = it is not allowed."},{t:"type",s:"I ___ (have to) get up early yesterday.",a:["had to"],hint:"Past form",x:"The past of must / have to is had to."},{t:"spot",s:"She can to speak three languages.",wrong:2,fix:"(no 'to')",x:"can + base form, without to: She can speak three languages."},{t:"match",pairs:[["must","it's necessary"],["mustn't","it isn't allowed"],["don't have to","it isn't necessary"],["should","it's a good idea"]],x:"What each modal means."},{t:"tiles",pre:"Do we",post:"a uniform at your school?",tiles:["have","to","wear","must","wearing"],a:["have","to","wear"],x:"Questions with have to: Do we have to…?"}]},{id:"b1u6l2",title:"Ability and possibility",items:[{t:"mc",s:"When I was five, I ___ swim.",o:["can","could","can't to","am able"],a:1,x:"could = ability in the past."},{t:"mc",s:"It ___ be John at the door – he said he might come.",o:["might","can't","mustn't","should to"],a:0,x:"might = maybe."},{t:"type",s:"Will you ___ come to my party?",a:["be able to"],hint:"Three words – can in the future",x:"will be able to = the future of can."},{t:"mc",s:"That ___ be true! I saw him an hour ago.",o:["can't","mustn't","shouldn't","needn't"],a:0,x:"can't = I'm sure it's not possible."},{t:"mc",s:"___ you help me with this box, please?",o:["Could","Must","Should","Ought"],a:0,x:"Could you…? = a polite request."},{t:"spot",s:"You should to try the new café.",wrong:2,fix:"(no 'to')",x:"should + base form: You should try the new café."},{t:"type",s:"You ___ (should / not) eat so much sugar.",a:["shouldn't","should not"],hint:"Advice – negative",x:"shouldn't + base form."},{t:"tiles",pre:"Sorry, I",post:"come to the meeting tomorrow.",tiles:["won't","be","able","to","can","couldn't"],a:["won't","be","able","to"],x:"won't be able to = can't in the future."}]}]},{id:"b1u7",title:"In, on, at and friends",part:"Vocabulary · Prepositions",color:"red",icon:"calendar",tips:["in + months, years, seasons; on + days and dates; at + clock times.","Many adjectives and verbs have their own preposition: good at, afraid of, depend on.","Learn them as chunks – interested in, listen to."],lessons:[{id:"b1u7l1",title:"Time",items:[{t:"mc",s:"My birthday is ___ May.",o:["in","on","at","by"],a:0,x:"in + months, years and seasons."},{t:"mc",s:"See you ___ Monday!",o:["in","on","at","by"],a:1,x:"on + days and dates."},{t:"mc",s:"The lesson starts ___ 9 o'clock.",o:["in","on","at","during"],a:2,x:"at + clock times."},{t:"type",s:"We always go skiing ___ winter.",a:["in"],hint:"One preposition",x:"in + seasons."},{t:"mc",s:"I'll finish the report ___ Friday – that's the deadline.",o:["until","by","since","in"],a:1,x:"by = not later than."},{t:"spot",s:"I'll see you in the weekend.",wrong:3,fix:"at",x:"British English says at the weekend."},{t:"match",pairs:[["at","night"],["on","Sunday morning"],["in","the evening"],["at","Christmas"]],x:"Fixed time expressions."},{t:"mc",s:"She has lived in Prague ___ ten years.",o:["since","for","during","ago"],a:1,x:"for + a period of time."}]},{id:"b1u7l2",title:"Place and fixed phrases",items:[{t:"mc",s:"The keys are ___ the table.",o:["in","on","at","by"],a:1,x:"on = on a surface."},{t:"mc",s:"I'll meet you ___ the bus stop.",o:["in","on","at","into"],a:2,x:"at + a point where you meet or wait."},{t:"type",s:"She's interested ___ photography.",a:["in"],hint:"One preposition",x:"interested in."},{t:"mc",s:"I'm really good ___ maths.",o:["in","at","on","for"],a:1,x:"good at something."},{t:"mc",s:"It depends ___ the weather.",o:["of","from","on","in"],a:2,x:"depend on."},{t:"spot",s:"I'm afraid from spiders.",wrong:2,fix:"of",x:"afraid of."},{t:"match",pairs:[["listen","to music"],["wait","for a bus"],["look","at a picture"],["think","about a problem"]],x:"Verbs with their prepositions."},{t:"tiles",pre:"We arrived",post:"late at night.",tiles:["in","London","to","on"],a:["in","London"],x:"arrive in + a city or country (arrive at + a building)."}]}]},{id:"b1u8",title:"Phrasal verbs for every day",part:"Vocabulary · Phrasal verbs",color:"blue",icon:"star",tips:["A phrasal verb is verb + a small word, and the meaning often changes: give up = stop trying.","Learn them with what they go with: put on a coat, fill in a form.","Reading Part 5 often tests the small word."],lessons:[{id:"b1u8l1",title:"At home",items:[{t:"mc",s:"Please ___ off the lights when you leave.",o:["turn","make","put on","take"],a:0,x:"turn off = stop a light or machine."},{t:"mc",s:"Can you ___ after my cat while I'm away?",o:["look","take","see","get"],a:0,x:"look after = take care of."},{t:"mc",s:"I'm ___ for my glasses – have you seen them?",o:["looking","finding","seeing","watching"],a:0,x:"look for = try to find."},{t:"type",s:"Don't give ___! You can do it.",a:["up"],hint:"One word",x:"give up = stop trying."},{t:"mc",s:"The plane ___ off at 6 am.",o:["took","got","went","put"],a:0,x:"take off = leave the ground."},{t:"match",pairs:[["put on","a coat"],["fill in","a form"],["pick up","the phone"],["throw away","rubbish"]],x:"Phrasal verbs with the things they go with."},{t:"spot",s:"Could you turn up the music? It's too loud.",wrong:3,fix:"down",x:"turn down = make quieter; turn up = make louder."},{t:"tiles",pre:"I need to",post:"early tomorrow.",tiles:["get","up","go","out","stand"],a:["get","up"],x:"get up = leave your bed."}]},{id:"b1u8l2",title:"With friends",items:[{t:"mc",s:"Let's ___ out tonight – there's a new film on.",o:["go","get","come","put"],a:0,x:"go out = leave home to have fun."},{t:"mc",s:"I ___ on well with my brother.",o:["get","go","take","come"],a:0,x:"get on (well) with = have a good relationship."},{t:"mc",s:"I ___ into an old friend at the supermarket.",o:["ran","went","got","came"],a:0,x:"run into = meet by chance."},{t:"type",s:"Can you pick me ___ from the airport?",a:["up"],hint:"One word",x:"pick somebody up = collect them."},{t:"mc",s:"They had an argument, but they ___ up the next day.",o:["made","did","got","took"],a:0,x:"make up = become friends again."},{t:"spot",s:"I'm busy now – I'll call you out later.",wrong:7,fix:"back",x:"call back = phone again later."},{t:"match",pairs:[["find out","discover"],["set off","start a journey"],["turn up","arrive"],["hang out","spend time together"]],x:"Common phrasal verbs."},{t:"tiles",pre:"We",post:"at the station at ten.",tiles:["set","off","put","up","took"],a:["set","off"],x:"set off = start a journey."}]}]},{id:"b1u9",title:"Some, any, much, many",part:"Grammar · Quantifiers",color:"green",icon:"book",tips:["Countable nouns: many, a few. Uncountable: much, a little.","some in positive sentences and offers; any in questions and negatives.","a lot of works with both."],lessons:[{id:"b1u9l1",title:"Countable or not?",items:[{t:"mc",s:"Is there ___ milk in the fridge?",o:["any","many","a","few"],a:0,x:"any in questions."},{t:"mc",s:"How ___ people came to the party?",o:["much","many","any","lot"],a:1,x:"many + countable plurals."},{t:"mc",s:"I haven't got ___ money left.",o:["many","much","a","few"],a:1,x:"much + uncountable nouns, often in negatives."},{t:"type",s:"Would you like ___ tea?",a:["some"],hint:"An offer",x:"some in offers and requests."},{t:"mc",s:"There are ___ apples in the bowl.",o:["a little","a few","much","any"],a:1,x:"a few + countable plurals."},{t:"spot",s:"Can you give me some informations?",wrong:5,fix:"information",x:"information is uncountable – no -s."},{t:"match",pairs:[["a piece of","advice"],["a bottle of","water"],["a slice of","bread"],["a bar of","chocolate"]],x:"Counting uncountable nouns."},{t:"tiles",pre:"We've got",post:"eggs – let's buy some more.",tiles:["only","a","few","little","much"],a:["only","a","few"],x:"a few + countable: only a few eggs."}]},{id:"b1u9l2",title:"A lot, too much, enough",items:[{t:"mc",s:"She has ___ friends at school.",o:["a lot of","much","a little","any"],a:0,x:"a lot of works with countable and uncountable nouns."},{t:"mc",s:"There's ___ sugar in this cake – it's too sweet.",o:["too much","too many","enough","a few"],a:0,x:"too much + uncountable = more than you want."},{t:"mc",s:"There aren't ___ chairs for everyone.",o:["enough","too","much","a little"],a:0,x:"enough + plural noun."},{t:"type",s:"There were too ___ people on the bus.",a:["many"],hint:"One word",x:"too many + countable plurals."},{t:"mc",s:"I need ___ help with my homework.",o:["a little","a few","many","few"],a:0,x:"a little + uncountable = some."},{t:"spot",s:"There is too many traffic in the city centre.",wrong:3,fix:"much",x:"traffic is uncountable: too much traffic."},{t:"mc",s:"Hardly ___ came to the meeting.",o:["anyone","someone","no one","everyone"],a:0,x:"hardly anyone = almost nobody."},{t:"tiles",pre:"I'd like",post:"information about the course, please.",tiles:["some","more","many","a"],a:["some","more"],x:"some more + uncountable in polite requests."}]}]},{id:"b1u10",title:"Joining ideas",part:"Grammar · Relative clauses & linking",color:"pink",icon:"pen",tips:["who for people, which for things, where for places, whose for possession.","because / as give a reason; so gives a result; but / although show a contrast.","Never use because and so in the same sentence."],lessons:[{id:"b1u10l1",title:"Who, which, where",items:[{t:"mc",s:"That's the man ___ lives next door.",o:["who","which","where","what"],a:0,x:"who for people."},{t:"mc",s:"This is the town ___ I was born.",o:["which","who","where","when"],a:2,x:"where for places."},{t:"mc",s:"The bike ___ I bought is red.",o:["who","which","where","whose"],a:1,x:"which (or that) for things."},{t:"type",s:"She's the girl ___ brother is in my class.",a:["whose"],hint:"Possession",x:"whose = his / her / their."},{t:"spot",s:"The film who we watched was scary.",wrong:2,fix:"which / that",x:"which or that for things – who is only for people."},{t:"match",pairs:[["who","people"],["which","things"],["where","places"],["when","times"]],x:"Relative pronouns."},{t:"tiles",pre:"I've got a friend",post:"in Spain.",tiles:["who","lives","which","live"],a:["who","lives"],x:"who + verb for people."},{t:"mc",s:"Do you remember the day ___ we met?",o:["when","where","which","who"],a:0,x:"when for times."}]},{id:"b1u10l2",title:"Because, so, but, although",items:[{t:"mc",s:"I stayed at home ___ I was ill.",o:["because","so","but","although"],a:0,x:"because gives the reason."},{t:"mc",s:"It was raining, ___ we took an umbrella.",o:["because","so","but","although"],a:1,x:"so gives the result."},{t:"mc",s:"___ it was cold, we went swimming.",o:["Although","Because","So","But"],a:0,x:"Although = in spite of the fact that."},{t:"type",s:"I like tea, ___ I don't like coffee.",a:["but"],hint:"A contrast",x:"but joins two contrasting ideas."},{t:"mc",s:"I went to bed early ___ I was tired.",o:["as","so","although","but"],a:0,x:"as = because."},{t:"spot",s:"Because it was late, so we took a taxi.",wrong:4,fix:"(no 'so')",x:"Use because OR so, not both."},{t:"match",pairs:[["because","a reason"],["so","a result"],["but","a contrast"],["also","adding an idea"]],x:"What linking words do."},{t:"tiles",pre:"We stayed inside",post:"the rain.",tiles:["because","of","so","although"],a:["because","of"],x:"because of + a noun: because of the rain."}]}]}],Object.assign(LZ.data.guide=LZ.data.guide||{},{b1u1:{idea:"Use the present simple for things that are always or usually true, and the present continuous for things happening now or just for a while.",rules:[["Habits and facts → present simple","She plays tennis every Saturday. Water boils at 100°C."],["Now or temporary → present continuous","Look! It's raining. I'm staying with my aunt this week."],["State verbs stay simple","I know the answer. I want a coffee."]],trap:["I'm not understanding this question.","I don't understand this question.","understand is a state verb – it stays in the simple form."],exam:"In Reading Part 6 and in your Writing, examiners notice the -s ending: he works, she doesn't, does it?"},b1u2:{idea:"The past simple tells what happened; the past continuous sets the scene – what was going on at the time.",rules:[["Finished actions → past simple","We visited Rome in 2022. Did you see the match?"],["Action in progress → past continuous","At 8 pm I was cooking dinner."],["Long action + short interruption","I was reading when the lights went out."]],trap:["When I was arriving, the film started.","When I arrived, the film started.","Short, completed actions use the past simple."],exam:"A story in Writing Part 2 needs both: the past continuous for the background, the past simple for the events."},b1u3:{idea:"The present perfect joins the past to now: experiences, recent news, and things that started before and are still true.",rules:[["Experience → ever / never","Have you ever tried Thai food? I've never been to Paris."],["Recent news → just / already / yet","I've just finished. Have you eaten yet?"],["Still true → for / since","I've lived here for two years / since 2023."]],trap:["I have seen him yesterday.","I saw him yesterday.","A finished time (yesterday, last week) needs the past simple."],exam:"Reading Part 6 often tests for, since, yet and already – read the whole sentence before you decide."},b1u4:{idea:"English has several futures: will for decisions and predictions, going to for plans, the present continuous for arrangements.",rules:[["Decision now / promise → will","I'll help you. I won't be late."],["Plan or evidence → going to","I'm going to study law. Look – it's going to fall!"],["Arrangement → present continuous","I'm meeting Anna at six."]],trap:["I will to call you tomorrow.","I will call you tomorrow.","No to after will."],exam:"In Writing Part 1 emails you often make plans and offers – mix will, going to and Shall I…?"},b1u5:{idea:"Compare two things with -er / more … than; pick the top one of a group with the -est / the most.",rules:[["Short adjectives","cheap → cheaper → the cheapest"],["Long adjectives","expensive → more expensive → the most expensive"],["The same / not the same","as tall as; not as expensive as"]],trap:["It's more easier than I thought.","It's easier than I thought.","Never use more and -er together."],exam:"Reading Part 5 sometimes tests than, as and enough – check the word after the gap."},b1u6:{idea:"Modal verbs add meaning to the main verb: obligation, advice, ability, possibility. They are followed by the base form.",rules:[["Obligation","You must / have to show your ticket."],["Not allowed vs not necessary","You mustn't smoke. You don't have to come."],["Advice and ability","You should rest. I can swim; I could swim when I was six."]],trap:["You don't have to park here – it's forbidden.","You mustn't park here – it's forbidden.","don't have to = not necessary; mustn't = not allowed."],exam:"Reading Part 1 notices are full of modals – must, mustn't, should, don't have to change the whole meaning."},b1u7:{idea:"Small words, big difference: time and place prepositions, and the prepositions that belong to certain verbs and adjectives.",rules:[["Time","in July, on Friday, at 6 o'clock, at the weekend"],["Place","in the room, on the wall, at the door"],["Fixed partners","good at, interested in, afraid of, depend on"]],trap:["I'm interested about music.","I'm interested in music.","Learn the adjective with its preposition."],exam:"Reading Part 6 (open cloze) often leaves out a preposition – look at the word before the gap."},b1u8:{idea:"A phrasal verb is a verb plus a small word, and together they have their own meaning.",rules:[["Everyday routines","get up, turn off, put on, look after"],["People","get on with, run into, make up, pick somebody up"],["Travel","set off, take off, check in"]],trap:["Please turn up the music – it's too loud.","Please turn down the music – it's too loud.","up = more, down = less."],exam:"Reading Part 5 gives four similar verbs – the small word after the gap usually decides."},b1u9:{idea:"Some nouns can be counted (apples), some can't (water, advice). The words before them change.",rules:[["Countable","many books, a few friends, How many…?"],["Uncountable","much time, a little milk, How much…?"],["Both","a lot of, some, any, enough"]],trap:["I need an advice.","I need some advice / a piece of advice.","advice, information and news are uncountable."],exam:"In Reading Part 6, check whether the noun after the gap is countable before you choose much or many."},b1u10:{idea:"Join short sentences into longer ones – it makes your writing clearer and gets you marks for organisation.",rules:[["Relative pronouns","the man who…, the book which…, the place where…, the girl whose…"],["Reason and result","because / as …; so …"],["Contrast","but; although + clause; because of + noun"]],trap:["Because I was tired, so I went home.","Because I was tired, I went home.","One linking word is enough."],exam:"Writing is marked for organisation: use a range of linking words, not just and and but."}}),LZ.data.tracks=LZ.data.tracks||{},(LZ.data.tracks.b1=LZ.data.tracks.b1||[]).push({id:"b1u11",title:"Used to and the past perfect",part:"Grammar · Past habits",color:"violet",icon:"calendar",tips:["used to + base form: past habits and states that aren't true now – I used to live in Rome.","Past perfect (had + past participle): something that happened before another past event.","didn't use to (no d) in negatives and questions: Did you use to…?"],lessons:[{id:"b1u11l1",title:"Things I used to do",items:[{t:"mc",s:"When I was little, I ___ afraid of the dark.",o:["used to be","use to be","was used to","am used to"],a:0,x:"used to + base form for a past state that isn't true now."},{t:"type",s:"We ___ (not / use to) have a car.",a:["didn't use to","did not use to"],hint:"The negative of used to",x:"didn't use to – no d after didn't."},{t:"mc",s:"___ you use to play in the street?",o:["Did","Were","Do","Had"],a:0,x:"Questions: Did you use to…?"},{t:"spot",s:"My grandfather used to working in a factory.",wrong:4,fix:"work",x:"used to + base form: used to work."},{t:"tiles",pre:"I",post:"football every day after school.",tiles:["used","to","play","played","use"],a:["used","to","play"],x:"used to + base form for a past habit."},{t:"mc",s:"There ___ be a cinema here, but now it's a supermarket.",o:["used to","uses to","is used to","was"],a:0,x:"There used to be… = there was, but there isn't now."},{t:"match",pairs:[["used to","a past habit"],["be used to","be familiar with"],["get used to","become familiar with"],["would","repeated actions in stories"]],x:"Different forms with used and would."},{t:"type",s:"She ___ (use to / have) long hair, but now it's short.",a:["used to have"],hint:"A past state",x:"used to have – it isn't true any more."}]},{id:"b1u11l2",title:"It had already happened",items:[{t:"mc",s:"When we arrived at the station, the train ___.",o:["had already left","already left","has already left","was already leaving"],a:0,x:"The train left before we arrived → past perfect."},{t:"type",s:"I was hungry because I ___ (not eat) all day.",a:["hadn't eaten","had not eaten"],hint:"Past perfect negative",x:"hadn't + past participle – before the moment I felt hungry."},{t:"mc",s:"She was nervous because she ___ on a plane before.",o:["had never been","never was","has never been","was never being"],a:0,x:"Before that moment in the past → had never been."},{t:"spot",s:"By the time I got home, everyone has gone to bed.",wrong:7,fix:"had",x:"Before a past moment → past perfect: had gone."},{t:"tiles",pre:"After she",post:"her homework, she went out.",tiles:["had","finished","has","finish"],a:["had","finished"],x:"The first of two past actions → had finished."},{t:"mc",s:"I recognised him because I ___ his photo in the newspaper.",o:["had seen","have seen","see","was seeing"],a:0,x:"Seeing the photo happened earlier → past perfect."},{t:"match",pairs:[["I had eaten","before another past action"],["I ate","a finished past action"],["I was eating","in progress in the past"],["I have eaten","past, with a result now"]],x:"Four ways to talk about the past."},{t:"type",s:"They ___ (already / start) the film when we got there.",a:["had already started"],hint:"Past perfect with already",x:"had + already + past participle."}]}]},{id:"b1u12",title:"If sentences",part:"Grammar · Conditionals",color:"amber",icon:"target",tips:["First conditional: if + present, will + verb – a real possibility.","Second conditional: if + past, would + verb – imaginary or unlikely.","unless = if not."],lessons:[{id:"b1u12l1",title:"If it rains…",items:[{t:"mc",s:"If it ___ tomorrow, we'll stay at home.",o:["rains","will rain","rained","would rain"],a:0,x:"First conditional: if + present simple (no will after if)."},{t:"type",s:"If you study hard, you ___ (pass) the exam.",a:["will pass","'ll pass"],hint:"The result in the future",x:"will + base form in the result clause."},{t:"mc",s:"I won't go ___ you come with me.",o:["unless","if","when","so"],a:0,x:"unless = if not: I won't go if you don't come."},{t:"spot",s:"If you heat ice, it melt.",wrong:5,fix:"melts",x:"Zero conditional for facts: if + present, present – it melts."},{t:"tiles",pre:"If we leave now,",post:"the train.",tiles:["we'll","catch","we","caught","would"],a:["we'll","catch"],x:"A real possibility → will + base form."},{t:"mc",s:"What will you do if you ___ the job?",o:["don't get","won't get","didn't get","not get"],a:0,x:"if + present simple – even when it's negative."},{t:"match",pairs:[["If you heat water to 100°C,","it boils."],["If it's sunny tomorrow,","we'll go to the beach."],["If I had more money,","I'd buy a car."],["Unless you hurry,","you'll be late."]],x:"Match the two halves."},{t:"type",s:"Take an umbrella in case it ___ (rain).",a:["rains"],hint:"in case + present",x:"in case + present simple."}]},{id:"b1u12l2",title:"If I were you…",items:[{t:"mc",s:"If I ___ a million pounds, I'd travel the world.",o:["had","have","will have","would have"],a:0,x:"Second conditional: if + past simple for something imaginary."},{t:"type",s:"If I were you, I ___ (tell) the teacher.",a:["would tell","'d tell"],hint:"Giving advice",x:"If I were you, I'd + base form."},{t:"mc",s:"She ___ happier if she lived nearer her friends.",o:["would be","will be","is","was"],a:0,x:"Imaginary present → would + base form."},{t:"spot",s:"If I know the answer, I'd tell you.",wrong:2,fix:"knew",x:"With I'd in the other half, you need the past: If I knew…"},{t:"tiles",pre:"What",post:"if you won the lottery?",tiles:["would","you","do","will","did"],a:["would","you","do"],x:"Question in the second conditional: What would you do…?"},{t:"mc",s:"If he ___ more carefully, he wouldn't have so many accidents.",o:["drove","drives","would drive","has driven"],a:0,x:"if + past simple in the second conditional."},{t:"type",s:"I'd come to the party if I ___ (not / have) to work.",a:["didn't have","did not have"],hint:"Second conditional",x:"if + didn't + base form."},{t:"mc",s:"Which sentence is about something unlikely or imaginary?",o:["If I were taller, I'd play basketball.","If it rains, I'll stay in.","If you press this, it starts.","If she calls, I'll tell you."],a:0,x:"were … 'd play = second conditional – imaginary."}]}]},{id:"b1u13",title:"The passive",part:"Grammar · Passive",color:"teal",icon:"doc",tips:["be + past participle: English is spoken here.","Use the passive when who does it is unknown or unimportant.","by + the person or thing that does the action: painted by Picasso."],lessons:[{id:"b1u13l1",title:"It is made in…",items:[{t:"mc",s:"Paper ___ from wood.",o:["is made","makes","is making","made"],a:0,x:"Present passive: is + past participle."},{t:"type",s:"This bridge ___ (build) in 1890.",a:["was built"],hint:"Past passive",x:"was + past participle."},{t:"mc",s:"The letters ___ every morning.",o:["are delivered","deliver","are delivering","delivered"],a:0,x:"Letters don't deliver themselves → passive."},{t:"spot",s:"The Mona Lisa was paint by Leonardo da Vinci.",wrong:4,fix:"painted",x:"be + past participle: was painted."},{t:"tiles",pre:"The windows",post:"every week.",tiles:["are","cleaned","clean","is"],a:["are","cleaned"],x:"Plural subject → are cleaned."},{t:"mc",s:"Our car ___ last night!",o:["was stolen","stole","is stolen","was stealing"],a:0,x:"Something happened to the car in the past → was stolen."},{t:"match",pairs:[["make","made"],["write","written"],["speak","spoken"],["send","sent"]],x:"Past participles for the passive."},{t:"type",s:"English ___ (speak) all over the world.",a:["is spoken"],hint:"Present passive",x:"is + past participle."}]},{id:"b1u13l2",title:"It has been done",items:[{t:"mc",s:"The meeting ___ until next week.",o:["has been postponed","has postponed","postponed","is postponing"],a:0,x:"Present perfect passive: has been + past participle."},{t:"type",s:"The tickets ___ (sell) already – there are none left.",a:["have been sold"],hint:"Present perfect passive",x:"have been + past participle."},{t:"mc",s:"The winner ___ tomorrow.",o:["will be announced","will announce","announces","is announcing"],a:0,x:"Future passive: will be + past participle."},{t:"spot",s:"The homework must be finish by Friday.",wrong:4,fix:"finished",x:"Modal passive: must be + past participle."},{t:"tiles",pre:"The new hospital",post:"next year.",tiles:["will","be","opened","open","is"],a:["will","be","opened"],x:"will be + past participle."},{t:"mc",s:"Who was ‘Romeo and Juliet’ written ___?",o:["by","from","of","with"],a:0,x:"by + the person who did it."},{t:"type",s:"Mistakes ___ (make) by everyone sometimes.",a:["are made"],hint:"Present passive",x:"are + past participle."},{t:"mc",s:"Which sentence is passive?",o:["The cake was eaten by the children.","The children ate the cake.","The children were eating.","The cake looks delicious."],a:0,x:"was eaten by… – the cake is the subject, and something happens to it."}]}]},{id:"b1u14",title:"Reported speech",part:"Grammar · Reported speech",color:"pink",icon:"pen",tips:["Move the tense back: ‘I'm tired’ → She said she was tired.","say (something) but tell somebody (something).","Questions: He asked where I lived – no question word order."],lessons:[{id:"b1u14l1",title:"She said that…",items:[{t:"mc",s:"‘I'm hungry,’ said Tom. → Tom said he ___ hungry.",o:["was","is being","has been","be"],a:0,x:"am/is → was."},{t:"type",s:"‘I can swim.’ → She said she ___ swim.",a:["could"],hint:"can → ?",x:"can → could."},{t:"mc",s:"He ___ me that he was leaving.",o:["told","said","spoke","talked"],a:0,x:"tell + person: He told me…"},{t:"spot",s:"She said me that she was busy.",wrong:1,fix:"told",x:"say doesn't take a person: She told me…"},{t:"tiles",pre:"‘I will help you.’ → He said he",post:"me.",tiles:["would","help","will","helped"],a:["would","help"],x:"will → would."},{t:"mc",s:"‘I've lost my keys.’ → She said she ___ her keys.",o:["had lost","has lost","lost","was losing"],a:0,x:"have done → had done."},{t:"match",pairs:[["am / is","was"],["will","would"],["can","could"],["have done","had done"]],x:"Tenses move back in reported speech."},{t:"type",s:"‘We're going home.’ → They said they ___ home.",a:["were going"],hint:"Present continuous → ?",x:"are going → were going."}]},{id:"b1u14l2",title:"He asked if…",items:[{t:"mc",s:"‘Where do you live?’ → She asked me where I ___.",o:["lived","do live","did live","live did"],a:0,x:"Reported questions use normal word order and move back: where I lived."},{t:"type",s:"‘Are you ready?’ → He asked ___ I was ready.",a:["if","whether"],hint:"A yes/no question",x:"Yes/no questions → if / whether."},{t:"mc",s:"The teacher told us ___ quiet.",o:["to be","be","being","that be"],a:0,x:"Orders: tell somebody to do something."},{t:"spot",s:"She asked me if I am tired.",wrong:5,fix:"was",x:"Move the tense back: if I was tired."},{t:"tiles",pre:"‘Don't touch it!’ → She told us",post:"it.",tiles:["not","to","touch","don't","touching"],a:["not","to","touch"],x:"Negative orders: tell somebody not to do something."},{t:"mc",s:"‘What time is it?’ → He asked what time ___.",o:["it was","was it","is it","it is being"],a:0,x:"Normal word order in reported questions: what time it was."},{t:"type",s:"‘Please sit down.’ → The doctor asked me ___ sit down.",a:["to"],hint:"ask somebody + ?",x:"ask somebody to do something."},{t:"mc",s:"Which sentence is correct?",o:["She asked where the station was.","She asked where was the station.","She asked where is the station.","She asked where the station is it."],a:0,x:"Question word + subject + verb."}]}]},{id:"b1u15",title:"-ing or to?",part:"Grammar · Verb patterns",color:"blue",icon:"star",tips:["enjoy, finish, mind, avoid + -ing: I enjoy swimming.","want, decide, hope, plan + to: I decided to leave.","After a preposition, always -ing: good at drawing, interested in learning."],lessons:[{id:"b1u15l1",title:"Enjoy doing, decide to do",items:[{t:"mc",s:"I really enjoy ___ in the sea.",o:["swimming","to swim","swim","swam"],a:0,x:"enjoy + -ing."},{t:"type",s:"We decided ___ (take) the train.",a:["to take"],hint:"decide + ?",x:"decide + to + base form."},{t:"mc",s:"Would you mind ___ the window?",o:["opening","to open","open","opened"],a:0,x:"mind + -ing."},{t:"spot",s:"She wants learning Japanese.",wrong:2,fix:"to learn",x:"want + to + base form."},{t:"tiles",pre:"Have you",post:"your essay?",tiles:["finished","writing","finish","to","write"],a:["finished","writing"],x:"finish + -ing."},{t:"mc",s:"They hope ___ a new house next year.",o:["to buy","buying","buy","bought"],a:0,x:"hope + to + base form."},{t:"match",pairs:[["enjoy","+ -ing"],["decide","+ to"],["avoid","+ -ing"],["promise","+ to"]],x:"Which pattern follows each verb?"},{t:"type",s:"He's thinking about ___ (change) his job.",a:["changing"],hint:"After a preposition",x:"Preposition + -ing."}]},{id:"b1u15l2",title:"Good at, afraid of",items:[{t:"mc",s:"I'm not very good at ___.",o:["cooking","to cook","cook","cooked"],a:0,x:"good at + -ing."},{t:"type",s:"Thank you for ___ (help) me.",a:["helping"],hint:"After for",x:"for + -ing."},{t:"mc",s:"She's afraid of ___ alone at night.",o:["walking","to walk","walk","walked"],a:0,x:"afraid of + -ing."},{t:"spot",s:"I'm interested in learn Spanish.",wrong:3,fix:"learning",x:"interested in + -ing."},{t:"tiles",pre:"I'm looking forward",post:"you soon.",tiles:["to","seeing","see","for"],a:["to","seeing"],x:"look forward to + -ing – here to is a preposition."},{t:"mc",s:"It's too cold ___ swimming today.",o:["to go","going","go","for going"],a:0,x:"too + adjective + to + base form."},{t:"type",s:"Remember ___ (lock) the door when you leave.",a:["to lock"],hint:"remember + ? (something you must do)",x:"remember to do = don't forget to do it."},{t:"mc",s:"My parents let me ___ up late at weekends.",o:["stay","to stay","staying","stayed"],a:0,x:"let + person + base form (no to)."}]}]},{id:"b1u16",title:"Make, do, have, take",part:"Vocabulary · Collocations",color:"green",icon:"book",tips:["make: a mistake, a noise, a decision, friends, money.","do: homework, the shopping, exercise, your best.","have / take: have a shower, have fun; take a photo, take an exam."],lessons:[{id:"b1u16l1",title:"Make or do?",items:[{t:"mc",s:"Try not to ___ so much noise.",o:["make","do","have","take"],a:0,x:"make a noise."},{t:"type",s:"Have you ___ (do) your homework yet?",a:["done"],hint:"The past participle of do",x:"do homework → have you done…?"},{t:"mc",s:"I always ___ a mistake with this word.",o:["make","do","take","have"],a:0,x:"make a mistake."},{t:"spot",s:"Can you make me a favour?",wrong:2,fix:"do",x:"do somebody a favour."},{t:"tiles",pre:"We need",post:"decision soon.",tiles:["to","make","a","do","the"],a:["to","make","a"],x:"make a decision."},{t:"mc",s:"She ___ the washing-up after dinner.",o:["did","made","took","had"],a:0,x:"do the washing-up."},{t:"match",pairs:[["make","a phone call"],["do","the ironing"],["take","a photo"],["have","a shower"]],x:"Verbs and the nouns they go with."},{t:"type",s:"I'll ___ my best to help.",a:["do"],hint:"do or make?",x:"do your best."}]},{id:"b1u16l2",title:"Take or have?",items:[{t:"mc",s:"Let's ___ a break for ten minutes.",o:["take","make","do","go"],a:0,x:"take a break."},{t:"type",s:"We ___ (have) a great time at the party last night.",a:["had"],hint:"The past of have",x:"have a great time."},{t:"mc",s:"How long does it ___ to get to the station?",o:["take","make","have","do"],a:0,x:"It takes (time) to do something."},{t:"spot",s:"I made a shower before breakfast.",wrong:1,fix:"had",x:"have a shower."},{t:"tiles",pre:"Don't forget",post:"medicine.",tiles:["to","take","your","make","do"],a:["to","take","your"],x:"take medicine."},{t:"mc",s:"She's going to ___ her driving test next month.",o:["take","make","go","put"],a:0,x:"take a test / an exam."},{t:"match",pairs:[["take","a seat"],["have","lunch"],["make","a cake"],["do","the housework"]],x:"More verb + noun pairs."},{t:"mc",s:"Which one is correct?",o:["take a photo","make a photo","do a photo","have a photo"],a:0,x:"take a photo."}]}]},{id:"b1u17",title:"Bored or boring?",part:"Vocabulary · Adjectives",color:"red",icon:"heart",tips:["-ed describes how you feel: I'm bored.","-ing describes what causes the feeling: The film is boring.","Order before a noun: opinion, size, age, colour – a lovely big old red bus."],lessons:[{id:"b1u17l1",title:"-ed or -ing?",items:[{t:"mc",s:"The lesson was so ___ that I fell asleep.",o:["boring","bored","bore","boredom"],a:0,x:"The lesson causes the feeling → boring."},{t:"type",s:"I was really ___ (surprise) when I saw him.",a:["surprised"],hint:"How I felt",x:"A feeling → -ed."},{t:"mc",s:"That was a ___ film – I couldn't stop watching.",o:["fascinating","fascinated","fascinate","fascination"],a:0,x:"The film causes the feeling → -ing."},{t:"spot",s:"I'm very interesting in history.",wrong:2,fix:"interested",x:"Your feeling → interested."},{t:"tiles",pre:"The news was",post:".",tiles:["really","shocking","shocked","shock"],a:["really","shocking"],x:"The news causes the feeling → shocking."},{t:"mc",s:"The children were ___ about the trip.",o:["excited","exciting","excite","excitement"],a:0,x:"How the children felt → excited."},{t:"match",pairs:[["annoyed","how you feel"],["annoying","what makes you feel it"],["confused","not understanding"],["confusing","hard to understand"]],x:"-ed and -ing adjectives."},{t:"type",s:"The instructions were very ___ (confuse).",a:["confusing"],hint:"Describing the instructions",x:"The instructions cause confusion → confusing."}]},{id:"b1u17l2",title:"A lovely old house",items:[{t:"mc",s:"She has ___ hair.",o:["long black","black long","longly black","long blacked"],a:0,x:"Size before colour: long black hair."},{t:"mc",s:"We stayed in a ___ hotel.",o:["beautiful small","small beautiful","beautifully small","small beauty"],a:0,x:"Opinion before size: a beautiful small hotel."},{t:"type",s:"It was a ___ (wonder) holiday.",a:["wonderful"],hint:"An adjective from wonder",x:"wonder + -ful."},{t:"spot",s:"It was a very sunshine day.",wrong:4,fix:"sunny",x:"You need an adjective: a sunny day."},{t:"tiles",pre:"They live in a",post:"house.",tiles:["lovely","old","white","whitely"],a:["lovely","old","white"],x:"Opinion – age – colour."},{t:"mc",s:"The weather was ___ than yesterday.",o:["worse","badder","more bad","worst"],a:0,x:"bad → worse → the worst."},{t:"type",s:"My sister is very ___ (help) – she always helps me with maths.",a:["helpful"],hint:"An adjective from help",x:"help + -ful."},{t:"match",pairs:[["hope","hopeful"],["danger","dangerous"],["friend","friendly"],["care","careful"]],x:"Nouns and their adjectives."}]}]},{id:"b1u18",title:"Building words",part:"Vocabulary · Word formation",color:"violet",icon:"pen",tips:["Nouns: -tion, -ment, -ness, -ity – information, enjoyment, happiness.","Adjectives: -ful, -less, -ous, -able – careful, careless, famous, comfortable.","Opposites: un-, in-, im-, dis- – unhappy, impossible, dislike."],lessons:[{id:"b1u18l1",title:"Nouns and adjectives",items:[{t:"mc",s:"Thank you for the ___ about the course.",o:["information","inform","informative","informed"],a:0,x:"After the you need a noun: information."},{t:"type",s:"She's a very ___ (success) businesswoman.",a:["successful"],hint:"An adjective",x:"success + -ful."},{t:"mc",s:"Her ___ surprised everyone.",o:["kindness","kind","kindly","kinder"],a:0,x:"After her you need a noun: kindness."},{t:"spot",s:"The concert was a great disappoint.",wrong:5,fix:"disappointment",x:"After a great you need a noun: a disappointment."},{t:"tiles",pre:"It's",post:"to cross the road here.",tiles:["very","dangerous","danger","dangerously"],a:["very","dangerous"],x:"After very you need an adjective."},{t:"mc",s:"We had a ___ time in Paris.",o:["wonderful","wonder","wondering","wonderfully"],a:0,x:"An adjective before time."},{t:"match",pairs:[["educate","education"],["develop","development"],["happy","happiness"],["possible","possibility"]],x:"Words and their nouns."},{t:"type",s:"The hotel room was very ___ (comfort).",a:["comfortable"],hint:"An adjective",x:"comfort + -able."}]},{id:"b1u18l2",title:"Opposites and adverbs",items:[{t:"mc",s:"It's ___ to finish all this work today.",o:["impossible","unpossible","inpossible","dispossible"],a:0,x:"im- before p: impossible."},{t:"type",s:"I ___ (like) cold weather – I prefer summer.",a:["dislike"],hint:"The opposite, with a prefix",x:"dis- + like."},{t:"mc",s:"She drives very ___.",o:["carefully","careful","care","careless"],a:0,x:"How she drives → an adverb."},{t:"spot",s:"He was very unpolite to the waiter.",wrong:3,fix:"impolite",x:"The opposite of polite is impolite."},{t:"tiles",pre:"Please speak",post:"– the baby's asleep.",tiles:["more","quietly","quiet","quieter"],a:["more","quietly"],x:"How to speak → adverb: more quietly."},{t:"mc",s:"The film was ___ – I didn't enjoy it at all.",o:["disappointing","undisappointing","disappointed","disappoint"],a:0,x:"The film causes the feeling → disappointing."},{t:"match",pairs:[["happy","unhappy"],["patient","impatient"],["honest","dishonest"],["correct","incorrect"]],x:"Opposites with prefixes."},{t:"type",s:"He answered the question ___ (correct).",a:["correctly"],hint:"An adverb",x:"correct + -ly."}]}]},{id:"b1u19",title:"Travel and holidays",part:"Vocabulary · Topics",color:"teal",icon:"calendar",tips:["journey = going from one place to another; trip = the journey and the visit; travel = the activity in general.","book a room, check in, check out, go sightseeing.","by car, by train, on foot – but in a car, on a train."],lessons:[{id:"b1u19l1",title:"Getting there",items:[{t:"mc",s:"How was your ___ to Scotland?",o:["trip","travel","travels","travelling"],a:0,x:"a trip to a place. travel is usually uncountable."},{t:"type",s:"We went to the museum ___ foot.",a:["on"],hint:"A preposition",x:"on foot."},{t:"mc",s:"The plane ___ off at 10.30.",o:["took","went","got","left"],a:0,x:"A plane takes off."},{t:"spot",s:"We travelled to Paris with train.",wrong:4,fix:"by",x:"by train, by car, by bus."},{t:"tiles",pre:"We",post:"at the hotel as soon as we arrived.",tiles:["checked","in","out","check"],a:["checked","in"],x:"check in = arrive and register."},{t:"mc",s:"Don't forget your ___ – you'll need it at the border.",o:["passport","luggage","map","receipt"],a:0,x:"You show your passport at a border."},{t:"match",pairs:[["departure","leaving"],["arrival","coming"],["luggage","bags"],["destination","where you're going"]],x:"Travel words."},{t:"type",s:"The train was ___ (delay) because of the snow.",a:["delayed"],hint:"A past participle",x:"was delayed = was late."}]},{id:"b1u19l2",title:"At the hotel",items:[{t:"mc",s:"I'd like to ___ a room for two nights.",o:["book","keep","buy","sell"],a:0,x:"book a room = reserve it."},{t:"type",s:"We went ___ in the old town and took lots of photos.",a:["sightseeing"],hint:"Visiting the famous places",x:"go sightseeing."},{t:"mc",s:"Breakfast is ___ in the price.",o:["included","contained","involved","consisted"],a:0,x:"included in the price."},{t:"spot",s:"Our room had a beautiful view to the sea.",wrong:6,fix:"of",x:"a view of something."},{t:"tiles",pre:"What time do we have to",post:"?",tiles:["check","out","in","checking"],a:["check","out"],x:"check out = leave the hotel."},{t:"mc",s:"The hotel was very ___ – it was right next to the beach.",o:["convenient","confident","complete","considerate"],a:0,x:"convenient = in a useful place."},{t:"match",pairs:[["single room","for one person"],["double room","for two people"],["reception","where you check in"],["receipt","proof that you paid"]],x:"Hotel words."},{t:"type",s:"Can I pay ___ credit card?",a:["by","with"],hint:"A preposition",x:"pay by (or with) card."}]}]},{id:"b1u20",title:"Asking questions",part:"Grammar · Questions",color:"amber",icon:"chart",tips:["Question word + auxiliary + subject + verb: Where do you live?","Subject questions have no do: Who called you?","Question tags: You're coming, aren't you? She didn't go, did she?"],lessons:[{id:"b1u20l1",title:"Where, why, how",items:[{t:"mc",s:"Where ___ you go on holiday last year?",o:["did","do","were","have"],a:0,x:"Past simple question: did + subject + base form."},{t:"type",s:"___ does the film start? – At eight.",a:["what time","when"],hint:"Asking about time",x:"What time / When…?"},{t:"mc",s:"Who ___ this picture?",o:["painted","did paint","did painted","was painting it"],a:0,x:"Who is the subject → no did: Who painted…?"},{t:"spot",s:"Where does she lives?",wrong:3,fix:"live",x:"After does, use the base form: Where does she live?"},{t:"tiles",pre:"How long",post:"here?",tiles:["have","you","lived","did","live"],a:["have","you","lived"],x:"How long + present perfect."},{t:"mc",s:"___ is your favourite subject?",o:["What","How","Who","Where"],a:0,x:"What is your favourite…?"},{t:"match",pairs:[["How much","a price"],["How often","a habit"],["How far","a distance"],["How long","a period of time"]],x:"Questions with how."},{t:"type",s:"___ bag is this? – It's mine.",a:["whose"],hint:"Asking about the owner",x:"Whose = belonging to who?"}]},{id:"b1u20l2",title:"…isn't it?",items:[{t:"mc",s:"It's a lovely day, ___?",o:["isn't it","is it","doesn't it","wasn't it"],a:0,x:"Positive sentence → negative tag."},{t:"type",s:"You don't like fish, ___?",a:["do you"],hint:"A question tag",x:"Negative sentence → positive tag."},{t:"mc",s:"She can swim, ___?",o:["can't she","can she","doesn't she","isn't she"],a:0,x:"Repeat the auxiliary: can → can't she?"},{t:"spot",s:"They went to Spain, weren't they?",wrong:4,fix:"didn't",x:"Past simple → didn't they?"},{t:"tiles",pre:"You've been there,",post:"?",tiles:["haven't","you","have","didn't"],a:["haven't","you"],x:"You've = you have → haven't you?"},{t:"mc",s:"Could you tell me where ___?",o:["the station is","is the station","the station","is station"],a:0,x:"Indirect questions keep normal word order."},{t:"type",s:"Do you know what time ___ (the shop / open)?",a:["the shop opens"],hint:"An indirect question",x:"Normal word order: the shop opens."},{t:"mc",s:"Let's go to the park, ___?",o:["shall we","will we","don't we","let's we"],a:0,x:"Let's… , shall we?"}]}]}),LZ.data.guide=LZ.data.guide||{},Object.assign(LZ.data.guide,{b1u11:{idea:"Two ways to look back: used to for things that were true in the past but aren't now, and the past perfect for the earlier of two past events.",rules:[["used to","I used to live in Rome. (I don't now.)"],["Negatives and questions","didn't use to, Did you use to…?"],["Past perfect","When I arrived, the film had started."]],trap:["I use to walk to school when I was young.","I used to walk to school when I was young.","Positive sentences need used (with d)."],exam:"Reading Parts 5 and 6 often test used to and had – look for time words like before, by the time and already."},b1u12:{idea:"Conditionals say what happens if something else happens – real possibilities or imaginary situations.",rules:[["Zero","If you heat ice, it melts. (always true)"],["First","If it rains, we'll stay in. (a real future)"],["Second","If I had time, I'd help. (imaginary now)"]],trap:["If it will rain, we'll stay in.","If it rains, we'll stay in.","No will straight after if."],exam:"Writing Part 1 emails often need a conditional: If you like, we could…"},b1u13:{idea:"In the passive, the thing that something happens to becomes the subject. It's common in news, science and descriptions of how things are made.",rules:[["Present","It is made in China."],["Past","It was built in 1890."],["Modal / future","It must be finished. It will be opened."]],trap:["The castle was build in 1500.","The castle was built in 1500.","Always the past participle after be."],exam:"Reading texts about history and science use the passive a lot – in Part 5, check whether the gap needs an active or a passive verb."},b1u14:{idea:"When you report what someone said, the tense usually moves one step back, and pronouns change.",rules:[["Statements","‘I'm tired.’ → She said (that) she was tired."],["Questions","‘Where do you live?’ → He asked where I lived."],["Orders","‘Sit down.’ → She told me to sit down."]],trap:["He said me that he was busy.","He told me that he was busy.","tell + person; say + (that)."],exam:"Stories in Writing Part 2 sound better with reported speech: She told me… He asked if…"},b1u15:{idea:"Some verbs are followed by -ing, others by to + verb – and after a preposition, it's always -ing.",rules:[["+ -ing","enjoy, finish, mind, avoid, suggest"],["+ to","want, decide, hope, plan, promise, agree"],["Preposition + -ing","good at cooking, before leaving, instead of waiting"]],trap:["I'm looking forward to see you.","I'm looking forward to seeing you.","Here to is a preposition, so -ing follows."],exam:"Writing Part 1 emails often end with ‘I'm looking forward to hearing from you’ – learn it by heart."},b1u16:{idea:"Some words simply go together. You make a mistake but do your homework – there's no rule, so learn them in pairs.",rules:[["make","a mistake, a decision, a noise, friends, money"],["do","homework, the shopping, exercise, a favour, your best"],["take / have","take a photo, a break, an exam; have a shower, a good time"]],trap:["I did a mistake in the test.","I made a mistake in the test.","It's always make a mistake."],exam:"Reading Part 5 often tests these pairs – the noun after the gap tells you the verb."},b1u17:{idea:"Adjectives ending in -ed describe feelings; -ing adjectives describe the thing that causes them. Several adjectives before a noun go in a fixed order.",rules:[["-ed","I'm bored / tired / interested."],["-ing","The film is boring / tiring / interesting."],["Order","opinion – size – age – colour: a lovely big old red bus"]],trap:["I'm boring in this lesson.","I'm bored in this lesson.","I'm boring = other people find me dull!"],exam:"Reading Part 5 often puts the -ed and -ing forms side by side – ask: is it a feeling or the cause?"},b1u18:{idea:"Add a few letters to the start or end of a word and you get a new word – a noun, an adjective, an adverb or an opposite.",rules:[["Nouns","-tion, -ment, -ness, -ity: information, enjoyment, kindness"],["Adjectives","-ful, -less, -ous, -able: careful, famous, comfortable"],["Opposites","un-, in-, im-, dis-: unhappy, incorrect, impossible, dislike"]],trap:["It was a very success party.","It was a very successful party.","Before a noun you need an adjective."],exam:"Writing is marked for range of vocabulary – using word families (success, successful, successfully) shows it."},b1u19:{idea:"Travel comes up in every paper – emails about trips, articles about holidays, notices at stations and hotels.",rules:[["Journey words","a journey, a trip, travel (uncountable)"],["Transport","by car / train / bus, on foot; get on / off a bus"],["Hotels","book a room, check in, check out, go sightseeing"]],trap:["I love travels.","I love travelling.","travel is usually uncountable."],exam:"Reading Part 1 notices at stations and hotels use this vocabulary – departures, platforms, delays."},b1u20:{idea:"English questions follow a pattern: question word, auxiliary, subject, verb. Tags and indirect questions make you sound natural and polite.",rules:[["Direct","Where do you live? What did she say?"],["Subject questions","Who called? What happened? (no do)"],["Tags and indirect","It's cold, isn't it? Could you tell me where the bank is?"]],trap:["Can you tell me where is the station?","Can you tell me where the station is?","Indirect questions keep normal word order."],exam:"Speaking Part 3 is easier with tags and questions: That's a good idea, isn't it? What do you think?"}}),LZ.data.tracks=LZ.data.tracks||{},LZ.data.tracks.c1=[{id:"c1u1",title:"Advanced collocations",part:"Part 1 · Collocations",color:"violet",icon:"star",tips:["C1 Part 1 tests strong collocations: bitterly disappointed, pose a threat, a heated debate.","Two options may mean the same – only one sits naturally with the words around the gap.","Collect collocations by topic: work, the environment, opinions."],lessons:[{id:"c1u1l1",title:"Adverbs that intensify",items:[{t:"mc",s:"She was ___ disappointed not to get the job.",o:["strongly","bitterly","heavily","highly"],a:1,x:"bitterly disappointed."},{t:"mc",s:"It is ___ unlikely that the match will go ahead.",o:["deeply","bitterly","highly","heavily"],a:2,x:"highly unlikely."},{t:"mc",s:"I'm ___ grateful for all your help.",o:["deeply","highly","heavily","widely"],a:0,x:"deeply grateful."},{t:"mc",s:"The two cases are ___ related.",o:["nearly","closely","tightly","narrowly"],a:1,x:"closely related."},{t:"type",s:"I ___ disagree with that decision.",a:["strongly"],hint:"An adverb beginning with s",x:"strongly disagree / strongly object."},{t:"match",pairs:[["painfully","slow"],["fully","aware"],["perfectly","clear"],["sorely","missed"]],x:"Adverb + adjective collocations."},{t:"mc",s:"The results were ___ different from what we expected.",o:["deeply","highly","vastly","bitterly"],a:2,x:"vastly different."},{t:"tiles",pre:"Everyone was",post:"by the news.",tiles:["deeply","shocked","highly","shocking"],a:["deeply","shocked"],x:"deeply shocked / moved / affected."}]},{id:"c1u1l2",title:"Verb + noun",items:[{t:"mc",s:"The new motorway could ___ a serious threat to wildlife.",o:["pose","make","give","set"],a:0,x:"pose a threat / a problem / a risk."},{t:"mc",s:"It's too early to ___ any conclusions.",o:["make","take","draw","get"],a:2,x:"draw a conclusion."},{t:"mc",s:"We worked all weekend to ___ the deadline.",o:["reach","meet","make","catch"],a:1,x:"meet a deadline."},{t:"type",s:"The report ___ light on the causes of the accident.",a:["sheds","shed","throws","threw"],hint:"A verb meaning 'helps to explain'",x:"shed / throw light on = help to explain."},{t:"mc",s:"The film ___ a lot of attention when it came out.",o:["attracted","pulled","won","gained up"],a:0,x:"attract attention."},{t:"match",pairs:[["reach","a compromise"],["run","a risk"],["take","into account"],["bear","in mind"]],x:"Verb + noun partners."},{t:"mc",s:"She ___ a strong case for changing the law.",o:["made","did","took","gave"],a:0,x:"make a case / an argument for something."},{t:"tiles",pre:"We need to",post:"before we decide.",tiles:["weigh","up","the","options","measure","pros"],a:["weigh","up","the","options"],x:"weigh up the options = consider them carefully."}]}]},{id:"c1u2",title:"Fixed phrases & idioms",part:"Part 1 · Fixed phrases",color:"blue",icon:"book",tips:["Idioms are fixed – you can't swap the words.","Learn the whole chunk with one example sentence.","Part 1 often removes the word learners forget: take something for granted."],lessons:[{id:"c1u2l1",title:"Everyday idioms",items:[{t:"mc",s:"We got to the station just in the ___ of time.",o:["nick","edge","point","moment"],a:0,x:"in the nick of time = only just in time."},{t:"mc",s:"He only visits his parents once in a blue ___.",o:["sky","moon","sun","day"],a:1,x:"once in a blue moon = very rarely."},{t:"mc",s:"Don't take your health for ___.",o:["given","granted","sure","true"],a:1,x:"take something for granted."},{t:"type",s:"The result came as no ___ – everyone expected it.",a:["surprise"],hint:"A noun",x:"come as no surprise."},{t:"mc",s:"The new stadium is a far ___ from the old one.",o:["way","cry","shout","call"],a:1,x:"a far cry from = very different from."},{t:"match",pairs:[["for the time being","for now"],["by and large","generally"],["on the spur of the moment","without planning"],["at short notice","with little warning"]],x:"Fixed phrases and what they mean."},{t:"mc",s:"She went to great ___ to make sure everyone felt welcome.",o:["lengths","efforts","troubles","extents"],a:0,x:"go to great lengths = make a big effort."},{t:"tiles",pre:"Whether he agrees or not is",post:".",tiles:["beside","the","point","next","matter"],a:["beside","the","point"],x:"beside the point = not relevant."}]},{id:"c1u2l2",title:"Idioms in context",items:[{t:"mc",s:"The deal fell ___ at the last minute.",o:["through","apart","down","over"],a:0,x:"fall through = fail to happen."},{t:"mc",s:"I'll keep an ___ on your bag while you get coffee.",o:["eye","ear","look","hand"],a:0,x:"keep an eye on = watch."},{t:"mc",s:"Finding a flat in the city centre is easier ___ than done.",o:["said","told","spoken","talked"],a:0,x:"easier said than done."},{t:"type",s:"Let's call it a ___ – we're all exhausted.",a:["day"],hint:"One word",x:"call it a day = stop working."},{t:"mc",s:"You've hit the ___ on the head – that's exactly the problem.",o:["nail","point","head","mark"],a:0,x:"hit the nail on the head = be exactly right."},{t:"spot",s:"I'm not in the mood of going out tonight.",wrong:5,fix:"for",x:"in the mood for (going out)."},{t:"match",pairs:[["cost an arm and a leg","be very expensive"],["a piece of cake","very easy"],["on the fence","undecided"],["the last straw","the final problem"]],x:"Common idioms."},{t:"tiles",pre:"The plan was",post:"from the start.",tiles:["doomed","to","failure","destined","for"],a:["doomed","to","failure"],x:"doomed to failure = certain to fail."}]}]},{id:"c1u3",title:"Inversion for emphasis",part:"Part 4 · Inversion",color:"red",icon:"bolt",tips:["After a negative or limiting word at the start, the auxiliary comes before the subject: Never have I seen…","Common openers: never, rarely, seldom, not only, no sooner, hardly, under no circumstances, only when.","In Part 4 the key word is often the negative opener."],lessons:[{id:"c1u3l1",title:"Never have I…",items:[{t:"mc",s:"Never ___ such a beautiful sunset.",o:["I have seen","have I seen","I saw","did I saw"],a:1,x:"Never + auxiliary + subject: Never have I seen…"},{t:"mc",s:"Rarely ___ he arrive on time.",o:["does","is","has","do"],a:0,x:"Rarely + does + subject + base form."},{t:"mc",s:"Not only ___ the exam, but she got the highest mark.",o:["she passed","did she pass","she did pass","passed she"],a:1,x:"Not only + did + subject + base form."},{t:"type",s:"No sooner ___ we sat down than the phone rang.",a:["had"],hint:"One auxiliary",x:"No sooner had + subject + past participle … than."},{t:"spot",s:"Under no circumstances you should open this door.",wrong:3,fix:"should you",x:"Under no circumstances should you open this door."},{t:"match",pairs:[["No sooner had I left","than it rained."],["Hardly had we arrived","when the lights went out."],["Not only is it cheap,","but it's also fast."],["Only then","did I understand."]],x:"Inverted openings and how they continue."},{t:"kwt",s1:"I have never tasted such delicious food.",key:"NEVER",pre:"",post:"such delicious food.",a:[["never have i"],["tasted"]],words:[3,6],x:"Never + have + I + past participle."},{t:"tiles",pre:"Seldom",post:"such a talented young player.",tiles:["have","we","seen","we've","saw"],a:["have","we","seen"],x:"Seldom + have + we + past participle."}]},{id:"c1u3l2",title:"Only when, not until, little",items:[{t:"mc",s:"Only when I got home ___ I had lost my wallet.",o:["I realised","did I realise","realised I","I did realise"],a:1,x:"Only when + clause, then inversion in the main clause: did I realise."},{t:"mc",s:"Not until the end of the film ___ who the killer was.",o:["we discovered","did we discover","we did discover","discovered we"],a:1,x:"Not until … + inversion."},{t:"mc",s:"Little ___ that she was about to become famous.",o:["she knew","did she know","knew she","she did know"],a:1,x:"Little did she know = she had no idea."},{t:"type",s:"Hardly had the match started ___ it began to pour.",a:["when"],hint:"One word",x:"Hardly … when."},{t:"kwt",s1:"She didn't realise the danger until later.",key:"ONLY",pre:"",post:"realise the danger.",a:[["only later"],["did she"]],words:[3,6],x:"Only later + did + subject + base form."},{t:"spot",s:"Not only he forgot my birthday, but he also lost my present.",wrong:2,fix:"did he forget",x:"Not only did he forget my birthday…"},{t:"mc",s:"At no time ___ the passengers in any danger.",o:["were","they were","was","did"],a:0,x:"At no time + were + subject."},{t:"kwt",s1:"As soon as I closed my eyes, the alarm went off.",key:"SOONER",pre:"No",post:"my eyes than the alarm went off.",a:[["sooner had i"],["closed"]],words:[3,6],x:"No sooner had + subject + past participle … than."}]}]},{id:"c1u4",title:"Cleft sentences",part:"Part 4 · Emphasis",color:"amber",icon:"target",tips:["It is/was … that … puts one part of the sentence in the spotlight.","What I need is… / What happened was… is another way to emphasise.","All I want is…, The reason why… and The thing that… work the same way."],lessons:[{id:"c1u4l1",title:"It was … that",items:[{t:"mc",s:"It was my brother ___ told me the news.",o:["who","which","what","whom he"],a:0,x:"It was + person + who / that."},{t:"mc",s:"It ___ only when I read the letter that I understood.",o:["was","is","has","had"],a:0,x:"It was only when … that …"},{t:"type",s:"It was in Paris ___ they first met.",a:["that"],hint:"One word",x:"It was + place + that."},{t:"mc",s:"___ I really admire about her is her honesty.",o:["What","That","Which","It"],a:0,x:"What + clause + is … = the thing that…"},{t:"spot",s:"It was the noise what woke me up.",wrong:4,fix:"that",x:"It was … that (not what)."},{t:"kwt",s1:"The weather ruined our holiday.",key:"WAS",pre:"It",post:"our holiday.",a:[["was the weather"],["that ruined","which ruined"]],words:[3,6],x:"It was + the thing + that + verb."},{t:"match",pairs:[["What I need","is a rest."],["All I want","is some sleep."],["The reason I left","was the noise."],["It was Tom","who called."]],x:"Ways to put one part in the spotlight."},{t:"tiles",pre:"What I found difficult",post:"the listening part.",tiles:["was","understanding","to","it","is"],a:["was","understanding"],x:"What … was + noun / -ing."}]},{id:"c1u4l2",title:"What, all, the reason",items:[{t:"mc",s:"All I want ___ a quiet evening at home.",o:["is","are","be","it is"],a:0,x:"All I want is… (singular)."},{t:"mc",s:"The reason ___ I called is to invite you.",o:["why","because","that why","what"],a:0,x:"The reason why … is …"},{t:"mc",s:"What happened ___ that the car broke down.",o:["was","is","had","did"],a:0,x:"What happened was (that) …"},{t:"type",s:"What I did ___ call the police.",a:["was"],hint:"One word",x:"What I did was + base form."},{t:"kwt",s1:"I only need five minutes of your time.",key:"ALL",pre:"",post:"five minutes of your time.",a:[["all i need"],["is"]],words:[3,6],x:"All I need is … = I only need …"},{t:"mc",s:"It's not the money ___ worries me, it's the time.",o:["that","what","who","it"],a:0,x:"It's not X that …, it's Y."},{t:"spot",s:"What I like most it is the atmosphere.",wrong:4,fix:"(no 'it')",x:"What I like most is the atmosphere."},{t:"kwt",s1:"His rudeness really annoys me.",key:"WHAT",pre:"",post:"his rudeness.",a:[["what really annoys me","what annoys me"],["is"]],words:[3,6],x:"What + clause + is + the thing."}]}]},{id:"c1u5",title:"Advanced word formation",part:"Part 3 · Prefixes & suffixes",color:"green",icon:"pen",tips:["C1 Part 3 often needs two changes at once: prefix + suffix (UNDERSTAND → misunderstanding).","Check the grammar of the gap: noun, adjective, adverb or verb – singular or plural?","Negative prefixes: un-, in-, im-, ir-, il-, dis-, mis-."],lessons:[{id:"c1u5l1",title:"Two changes at once",items:[{t:"wf",s:"There was a ___ between the two teams about the rules.",w:"UNDERSTAND",a:["misunderstanding"],x:"Prefix mis- + noun: a misunderstanding."},{t:"wf",s:"It was ___ of him to leave the children alone.",w:"RESPONSIBLE",a:["irresponsible"],x:"ir- before r: irresponsible."},{t:"wf",s:"Customer ___ has dropped since the changes.",w:"SATISFY",a:["satisfaction"],x:"A noun after customer: satisfaction."},{t:"wf",s:"His handwriting is almost ___.",w:"LEGIBLE",a:["illegible"],x:"il- before l: illegible."},{t:"wf",s:"The advert was deliberately ___.",w:"LEAD",a:["misleading"],x:"mis- + -ing adjective: misleading."},{t:"wf",s:"We need to ___ security at the entrance.",w:"STRONG",a:["strengthen"],x:"A verb from strong: strengthen."},{t:"wf",s:"The ___ of the museum took three years.",w:"MODERN",a:["modernisation","modernization"],x:"modern → modernise → modernisation."},{t:"wf",s:"Her ___ to give up impressed everyone.",w:"REFUSE",a:["refusal"],x:"refuse → refusal."}]},{id:"c1u5l2",title:"Adjectives, adverbs and nouns",items:[{t:"wf",s:"The film was ___ long – almost four hours.",w:"EXCEPTION",a:["exceptionally"],x:"An adverb before an adjective: exceptionally."},{t:"wf",s:"There is a ___ of qualified nurses.",w:"SHORT",a:["shortage"],x:"short → shortage."},{t:"wf",s:"He can be completely ___ to other people's feelings.",w:"SENSE",a:["insensitive"],x:"Two changes: in- + -itive → insensitive."},{t:"wf",s:"The ___ of the new vaccine took two years.",w:"DEVELOP",a:["development"],x:"develop → development."},{t:"wf",s:"She's a ___ – she writes for three newspapers.",w:"JOURNAL",a:["journalist"],x:"journal → journalist."},{t:"wf",s:"The instructions were ___ – nobody could follow them.",w:"HELP",a:["unhelpful"],x:"un- + -ful: unhelpful."},{t:"wf",s:"Prices have risen ___ this year.",w:"DRAMA",a:["dramatically"],x:"drama → dramatic → dramatically."},{t:"wf",s:"Good ___ skills are essential for this job.",w:"COMMUNICATE",a:["communication"],x:"A noun used like an adjective: communication skills."}]}]},{id:"c1u6",title:"Dependent prepositions",part:"Part 2 · Prepositions",color:"teal",icon:"doc",tips:["Many C1 words carry a fixed preposition: in charge of, with regard to, on the verge of.","Nouns too: a solution to, an increase in, a demand for.","Part 2 often removes the preposition from a fixed phrase."],lessons:[{id:"c1u6l1",title:"Adjectives and nouns",items:[{t:"mc",s:"She seemed completely oblivious ___ the danger.",o:["to","at","for","with"],a:0,x:"oblivious to."},{t:"mc",s:"There has been a sharp increase ___ crime.",o:["of","in","on","for"],a:1,x:"an increase in (the thing that goes up)."},{t:"type",s:"Is there a solution ___ this problem?",a:["to"],hint:"One preposition",x:"a solution to."},{t:"mc",s:"The company is heavily reliant ___ foreign investment.",o:["of","on","to","in"],a:1,x:"reliant on."},{t:"mc",s:"He's in charge ___ the whole department.",o:["for","of","with","on"],a:1,x:"in charge of."},{t:"spot",s:"He is very capable to doing the job.",wrong:4,fix:"of",x:"capable of + -ing."},{t:"match",pairs:[["a demand","for"],["an effect","on"],["an alternative","to"],["a lack","of"]],x:"Noun + preposition."},{t:"tiles",pre:"The town is",post:"a major change.",tiles:["on","the","verge","of","edge","at"],a:["on","the","verge","of"],x:"on the verge of = very close to."}]},{id:"c1u6l2",title:"Verbs and fixed phrases",items:[{t:"mc",s:"Please refrain ___ smoking in the building.",o:["of","from","to","against"],a:1,x:"refrain from + -ing."},{t:"mc",s:"The decision was made ___ consultation with the staff.",o:["in","on","by","with"],a:0,x:"in consultation with."},{t:"type",s:"She insisted ___ paying for dinner.",a:["on"],hint:"One preposition",x:"insist on + -ing."},{t:"mc",s:"___ regard to your complaint, we have issued a refund.",o:["With","In","On","By"],a:0,x:"with regard to = about."},{t:"mc",s:"The rise in prices is attributed ___ higher energy costs.",o:["for","to","with","on"],a:1,x:"attribute something to something."},{t:"spot",s:"He was accused for stealing the money.",wrong:3,fix:"of",x:"accuse somebody of something."},{t:"match",pairs:[["object","to"],["cope","with"],["account","for"],["abide","by"]],x:"Verb + preposition."},{t:"tiles",pre:"The plan was abandoned",post:"the cost.",tiles:["on","account","of","because","due"],a:["on","account","of"],x:"on account of = because of."}]}]},{id:"c1u7",title:"Mixed conditionals & wishes",part:"Part 4 · Conditionals",color:"pink",icon:"heart",tips:["Mixed conditionals join a past condition to a present result (If I had studied, I'd be a doctor now) – or the reverse.","wish / if only + past perfect for past regrets; + would for annoying habits.","Also: provided that, as long as, but for, otherwise, had I known."],lessons:[{id:"c1u7l1",title:"Mixed conditionals",items:[{t:"mc",s:"If I ___ harder at school, I'd have a better job now.",o:["studied","had studied","would study","study"],a:1,x:"Past condition (had studied) → present result (I'd have)."},{t:"mc",s:"If she weren't so shy, she ___ the prize last night.",o:["would accept","would have accepted","accepted","had accepted"],a:1,x:"Present characteristic → past result: would have + past participle."},{t:"type",s:"___ I known about the party, I would have come.",a:["had"],hint:"One word – inversion",x:"Had I known = If I had known."},{t:"mc",s:"___ your help, I would never have finished.",o:["But for","Unless","Provided","Otherwise"],a:0,x:"But for + noun = if it hadn't been for."},{t:"kwt",s1:"I didn't know you were ill, so I didn't visit you.",key:"HAD",pre:"If",post:"you were ill, I would have visited you.",a:[["i had"],["known"]],words:[3,6],x:"Third conditional: If I had known…"},{t:"spot",s:"If I would know the answer, I would tell you.",wrong:2,fix:"knew",x:"No would in the if-clause: If I knew the answer, I would tell you."},{t:"mc",s:"You can borrow my car ___ you drive carefully.",o:["provided","unless","otherwise","in case"],a:0,x:"provided (that) = only if."},{t:"tiles",pre:"If he",post:"the bus, he'd be here by now.",tiles:["hadn't","missed","didn't","miss","wouldn't"],a:["hadn't","missed"],x:"A past condition with a present result."}]},{id:"c1u7l2",title:"Wishes and regrets",items:[{t:"mc",s:"I wish I ___ so much yesterday.",o:["didn't eat","hadn't eaten","wouldn't eat","haven't eaten"],a:1,x:"wish + past perfect for a past regret."},{t:"mc",s:"I wish you ___ interrupting me!",o:["would stop","stopped","had stopped","stop"],a:0,x:"wish + would for an annoying habit you want changed."},{t:"type",s:"If ___ I had listened to your advice!",a:["only"],hint:"One word",x:"If only + past perfect = a strong past regret."},{t:"mc",s:"It's high time we ___ home.",o:["go","went","had gone","will go"],a:1,x:"It's (high) time + past simple."},{t:"kwt",s1:"It's a pity I didn't apply for that job.",key:"WISH",pre:"I",post:"for that job.",a:[["wish i had","wish that i had","wish i'd"],["applied"]],words:[3,6],x:"wish + past perfect."},{t:"mc",s:"I'd rather you ___ tell anyone about this.",o:["didn't","don't","won't","hadn't"],a:0,x:"would rather + subject + past simple."},{t:"spot",s:"I wish I can speak Japanese.",wrong:3,fix:"could",x:"wish + a past form: I wish I could speak Japanese."},{t:"kwt",s1:"I regret not going to university.",key:"ONLY",pre:"If",post:"to university.",a:[["only i had","only i'd"],["gone"]],words:[3,6],x:"If only + past perfect."}]}]},{id:"c1u8",title:"Passives, reporting & causatives",part:"Part 4 · Passives",color:"violet",icon:"doc",tips:["It is said that… = He is said to…; for the past: is said to have done.","have / get something done when someone else does it for you.","Modal passives: must be done, should have been done."],lessons:[{id:"c1u8l1",title:"Is said to have…",items:[{t:"mc",s:"The painting is believed ___ stolen in 1990.",o:["to be","to have been","being","having"],a:1,x:"A past event → to have been + past participle."},{t:"mc",s:"He is said ___ a fortune from his grandfather.",o:["to inherit","to have inherited","inheriting","inherited"],a:1,x:"The past → to have + past participle."},{t:"type",s:"It ___ thought that the fire started in the kitchen.",a:["is"],hint:"One word",x:"It is thought that…"},{t:"kwt",s1:"People say that the castle is haunted.",key:"SAID",pre:"The castle",post:"haunted.",a:[["is said"],["to be"]],words:[3,6],x:"is said + to be (present)."},{t:"mc",s:"The suspect is thought ___ the country last week.",o:["to leave","to have left","leaving","left"],a:1,x:"last week = the past → to have left."},{t:"spot",s:"The report must be finish by Friday.",wrong:4,fix:"finished",x:"Modal passive: must be + past participle."},{t:"match",pairs:[["It is said","that she's rich."],["She is said","to be rich."],["It was reported","that he had left."],["He was reported","to have left."]],x:"Two ways to report."},{t:"kwt",s1:"Experts believe that the building was designed by a woman.",key:"BELIEVED",pre:"The building",post:"designed by a woman.",a:[["is believed"],["to have been"]],words:[3,6],x:"is believed + to have been + past participle."}]},{id:"c1u8l2",title:"Have it done",items:[{t:"mc",s:"I'm having my kitchen ___ next week.",o:["paint","painted","painting","to paint"],a:1,x:"have + object + past participle."},{t:"mc",s:"She got her bag ___ on the train.",o:["stolen","steal","stealing","to steal"],a:0,x:"get something + past participle for something bad that happened to you."},{t:"type",s:"We need to ___ the roof repaired before winter.",a:["have","get"],hint:"One verb",x:"have / get something done."},{t:"kwt",s1:"A mechanic is checking my car.",key:"HAVING",pre:"I",post:"by a mechanic.",a:[["am having my car"],["checked"]],words:[3,6],x:"have + object + past participle: I'm having my car checked."},{t:"mc",s:"This work should ___ done yesterday.",o:["be","have been","been","have"],a:1,x:"should have been + past participle for something that didn't happen."},{t:"spot",s:"She had her nails do yesterday.",wrong:4,fix:"done",x:"have something done."},{t:"mc",s:"The results are expected ___ published tomorrow.",o:["to be","to have been","being","be"],a:0,x:"The future → to be + past participle."},{t:"tiles",pre:"The new bridge",post:"next year.",tiles:["will","be","opened","open","has","been"],a:["will","be","opened"],x:"Future passive: will be + past participle."}]}]},{id:"c1u9",title:"Linking ideas",part:"Part 2 · Linkers",color:"amber",icon:"chart",tips:["Contrast: nevertheless, whereas, even though, despite (+ noun / -ing).","Addition and result: moreover, furthermore, consequently, hence.","Grammar decides: despite + noun, although + clause."],lessons:[{id:"c1u9l1",title:"Contrast",items:[{t:"mc",s:"___ the heavy rain, the match went ahead.",o:["Despite","Although","However","Even"],a:0,x:"Despite + noun."},{t:"mc",s:"___ she was tired, she kept working.",o:["Despite","In spite","Even though","Nevertheless"],a:2,x:"Even though + clause."},{t:"type",s:"In spite ___ the cost, they bought the house.",a:["of"],hint:"One word",x:"in spite of + noun."},{t:"mc",s:"The job is well paid; ___, the hours are very long.",o:["nevertheless","despite","although","whereas"],a:0,x:"nevertheless joins two sentences with a contrast."},{t:"mc",s:"My brother loves football, ___ I prefer tennis.",o:["whereas","despite","however","nevertheless"],a:0,x:"whereas compares two contrasting facts in one sentence."},{t:"spot",s:"Despite of the delay, we arrived on time.",wrong:1,fix:"(no 'of')",x:"despite (no of) – or in spite of."},{t:"match",pairs:[["although","+ clause"],["despite","+ noun / -ing"],["however","new sentence"],["whereas","compares two facts"]],x:"The grammar of contrast linkers."},{t:"kwt",s1:"Although it was expensive, we booked the hotel.",key:"SPITE",pre:"In",post:"we booked the hotel.",a:[["spite of"],["the high price","its high price","the price","the cost","it being expensive"]],words:[3,6],x:"in spite of + noun or -ing."}]},{id:"c1u9l2",title:"Adding and concluding",items:[{t:"mc",s:"The flat is small. ___, it's too expensive.",o:["Moreover","Whereas","Despite","Although"],a:0,x:"Moreover adds a further point."},{t:"mc",s:"He missed the train and ___ was late for the interview.",o:["consequently","moreover","whereas","despite"],a:0,x:"consequently = as a result."},{t:"type",s:"In addition ___ teaching, she writes novels.",a:["to"],hint:"One word",x:"In addition to + noun / -ing."},{t:"mc",s:"She left early ___ as not to miss the last bus.",o:["so","such","in order","that"],a:0,x:"so as not to + base form."},{t:"mc",s:"___ all the difficulties, the project was a success.",o:["Notwithstanding","Nevertheless","Whereas","Moreover"],a:0,x:"notwithstanding = despite (formal)."},{t:"spot",s:"Furthermore being cheap, it's very reliable.",wrong:0,fix:"Besides",x:"Besides + -ing adds a point; furthermore starts a new sentence."},{t:"match",pairs:[["hence","for this reason"],["thereby","by doing this"],["whereby","by which"],["albeit","although"]],x:"Formal linkers."},{t:"tiles",pre:"The plan was rejected",post:"it was too expensive.",tiles:["on","the","grounds","that","because","reason"],a:["on","the","grounds","that"],x:"on the grounds that = because (formal)."}]}]},{id:"c1u10",title:"Phrasal verbs at C1",part:"Part 1 · Phrasal verbs",color:"blue",icon:"star",tips:["C1 phrasal verbs are often abstract: come up with a plan, bring about change, rule out an option.","Many have a formal one-word twin – learn the pair: rule out = exclude.","In Part 1 the particle is often given – you choose the verb."],lessons:[{id:"c1u10l1",title:"Ideas and plans",items:[{t:"mc",s:"The committee ___ forward a new proposal.",o:["put","brought","came","set"],a:0,x:"put forward = suggest."},{t:"mc",s:"Scientists ___ out a series of experiments.",o:["carried","took","made","did"],a:0,x:"carry out = do (research, tests)."},{t:"mc",s:"We need to ___ up with a better solution.",o:["come","bring","put","make"],a:0,x:"come up with = think of."},{t:"type",s:"The police have ___ out the possibility of murder.",a:["ruled"],hint:"Past participle",x:"rule out = exclude."},{t:"mc",s:"The new law ___ about a huge change in attitudes.",o:["brought","came","set","took"],a:0,x:"bring about = cause to happen."},{t:"match",pairs:[["draw up","prepare (a plan)"],["phase out","remove gradually"],["back down","stop insisting"],["opt out","choose not to take part"]],x:"C1 phrasal verbs."},{t:"spot",s:"They carried on a survey of local residents.",wrong:2,fix:"out",x:"carry out a survey; carry on = continue."},{t:"tiles",pre:"The government plans to",post:"coal power by 2030.",tiles:["phase","out","face","off","put"],a:["phase","out"],x:"phase out = stop using gradually."}]},{id:"c1u10l2",title:"People and situations",items:[{t:"mc",s:"Despite the pressure, she refused to back ___.",o:["down","off","away","out"],a:0,x:"back down = stop insisting."},{t:"mc",s:"The meeting was ___ off because the director was ill – it won't take place at all.",o:["called","put","set","taken"],a:0,x:"call off = cancel (put off = postpone)."},{t:"type",s:"I can't ___ up with this noise any longer.",a:["put"],hint:"One verb",x:"put up with = tolerate."},{t:"mc",s:"The fire alarm was ___ off by smoke from the kitchen.",o:["set","called","put","turned"],a:0,x:"set off = cause (an alarm) to start."},{t:"mc",s:"It took her months to ___ over the illness.",o:["get","come","take","go"],a:0,x:"get over = recover from."},{t:"spot",s:"Sales picked out after the new advertising campaign.",wrong:2,fix:"up",x:"pick up = improve."},{t:"match",pairs:[["fall out","argue"],["bring up","mention"],["turn down","refuse"],["take on","employ"]],x:"More C1 phrasal verbs."},{t:"tiles",pre:"The company had to",post:"fifty workers.",tiles:["lay","off","lie","out","let"],a:["lay","off"],x:"lay off = dismiss (because there's no work)."}]}]}],Object.assign(LZ.data.guide=LZ.data.guide||{},{c1u1:{idea:"At C1, the question is rarely what a word means – it's which word naturally goes with its neighbours.",rules:[["Adverb + adjective","bitterly disappointed, highly unlikely, deeply grateful"],["Verb + noun","pose a threat, draw a conclusion, meet a deadline"],["Adjective + noun","a heated debate, a narrow escape, heavy traffic"]],trap:["She was strongly disappointed with the result.","She was bitterly disappointed with the result.","strongly goes with opinions (strongly disagree); disappointment is bitter."],exam:"In Part 1, read the words on both sides of the gap – the collocation is usually with the word right after it."},c1u2:{idea:"Fixed phrases work like single words: every word is chosen, and changing one breaks them.",rules:[["Time","in the nick of time, once in a blue moon, for the time being"],["Effort and difference","go to great lengths, a far cry from"],["Reaction","take something for granted, come as no surprise, beside the point"]],trap:["It came as no surprised to anyone.","It came as no surprise to anyone.","come as + a noun: no surprise."],exam:"Part 1 loves phrases with a missing noun or verb – think of the whole phrase before looking at the options."},c1u3:{idea:"Putting a negative or limiting word first makes a sentence dramatic – and then the auxiliary jumps in front of the subject, as in a question.",rules:[["Never / rarely / seldom","Rarely do we see such talent."],["Not only … but also","Not only did she win, but she also broke the record."],["No sooner … than / Hardly … when","No sooner had we arrived than it started to rain."]],trap:["Never I have seen such a mess.","Never have I seen such a mess.","After a negative opener, put the auxiliary before the subject."],exam:"Part 4: if the key word is a negative adverb (SELDOM, ONLY, SOONER), you almost certainly need inversion."},c1u4:{idea:"A cleft sentence splits one idea in two so you can point at the most important part.",rules:[["It was … that","It was Sarah that broke the window (not Tom)."],["What … is / was","What I need is a long holiday."],["All / The reason / The thing","All I want is some peace. The reason why I left was the noise."]],trap:["What I need it is more time.","What I need is more time.","Don't add it after the what-clause."],exam:"Part 4 tests It was only when … that … and What … was … – count your words, these structures use several."},c1u5:{idea:"At C1 the word in capitals often needs a prefix and a suffix, or a change inside the word.",rules:[["Negative prefixes","irresponsible, illegible, dissatisfied, misleading"],["Noun suffixes","-ment, -ness, -ity, -ance, -ence, -ship, -al"],["Making verbs","strengthen, modernise, enable"]],trap:["The results were unreliability.","The results were unreliable.","After were you need an adjective."],exam:"Read the whole sentence: a negative meaning in the context tells you a prefix is needed."},c1u6:{idea:"Many words come with their own preposition, and C1 texts are full of them.",rules:[["Adjective + preposition","capable of, oblivious to, reliant on"],["Noun + preposition","a solution to, an increase in, a demand for"],["Fixed phrases","in charge of, on the verge of, with regard to"]],trap:["There is no solution for this problem.","There is no solution to this problem.","solution to (not for)."],exam:"In Part 2, when the gap sits between a noun or adjective and a phrase, try a preposition first."},c1u7:{idea:"At C1 conditionals cross time: a past event with a present result, or a lasting situation with a past result.",rules:[["Past → present","If I had taken the job, I would be living in Rome now."],["Present → past","If she weren't so shy, she would have spoken up."],["Without if","Provided that…, But for your help…, Had I known…"]],trap:["If I would have known, I would have come.","If I had known, I would have come.","No would in the if-clause."],exam:"Part 4 likes inverted conditionals: Had I known… = If I had known…; Should you need… = If you need…"},c1u8:{idea:"C1 passives let you report what people believe, and say who did something for you – without always naming them.",rules:[["Reporting","It is thought that he left. → He is thought to have left."],["Causative","I had my car repaired. I'm getting my hair cut."],["Modal passive","It should have been done yesterday."]],trap:["She is believed to live in Paris in 2010.","She is believed to have lived in Paris in 2010.","For the past, use to have + past participle."],exam:"Part 4 regularly turns People say that… into … is said to… – watch the tense."},c1u9:{idea:"C1 texts are judged on how ideas connect – and Part 2 often removes the connector.",rules:[["Contrast","Despite the rain… / Even though it rained… / It was hard; nevertheless, …"],["Addition","Moreover, … / In addition to + -ing …"],["Result and purpose","Consequently, … / so as not to … / on the grounds that …"]],trap:["Despite it was raining, we went out.","Despite the rain, we went out.","despite + noun or -ing, never a clause."],exam:"In Part 2, look at what follows the gap: a clause, a noun or an -ing form decides which linker fits."},c1u10:{idea:"At C1, phrasal verbs describe ideas and processes, not just physical actions.",rules:[["Ideas and plans","come up with, put forward, draw up, carry out"],["Change and cause","bring about, phase out, set off"],["Decisions","rule out, opt out, back down, call off"]],trap:["They carried on an investigation into the crash.","They carried out an investigation into the crash.","carry out = do; carry on = continue."],exam:"In Part 1 all four verbs may take the same particle – ask which one gives the meaning."}}),LZ.data.tracks=LZ.data.tracks||{},(LZ.data.tracks.c1=LZ.data.tracks.c1||[]).push({id:"c1u11",title:"Participle clauses",part:"Part 2 · Participles",color:"teal",icon:"doc",tips:["An -ing clause for actions at the same time or a reason: Feeling tired, she went to bed.","Having + past participle for an earlier action: Having finished, he left.","A past participle clause has a passive meaning: Built in 1900, the house…"],lessons:[{id:"c1u11l1",title:"Having done, done",items:[{t:"mc",s:"___ the email, she closed her laptop.",o:["Having sent","Sent","Having sending","To have send"],a:0,x:"Having + past participle: the first of two actions."},{t:"mc",s:"___ in 1890, the bridge is still in use today.",o:["Built","Building","Having building","To build"],a:0,x:"Past participle clause with a passive meaning: (it was) built."},{t:"type",s:"___ (not / know) what to say, he stayed silent.",a:["not knowing"],hint:"A reason, with -ing",x:"Not + -ing at the start of the clause."},{t:"spot",s:"Having finish the report, she went home.",wrong:1,fix:"finished",x:"Having + past participle: Having finished."},{t:"kwt",s1:"Because she was exhausted, she went straight to bed.",key:"FEELING",pre:"",post:"went straight to bed.",a:[["feeling exhausted"],["she"]],words:[3,6],x:"A participle clause giving the reason: Feeling exhausted, she…"},{t:"wf",s:"The ___ results surprised everyone.",w:"EXPECT",a:["unexpected"],x:"Negative participle adjective: unexpected."},{t:"tiles",pre:"Having",post:"the film before, I knew the ending.",tiles:["already","seen","saw","seeing"],a:["already","seen"],x:"Having (already) + past participle."},{t:"mc",s:"The children, ___ by the noise, woke up.",o:["frightened","frightening","having frightened","to frighten"],a:0,x:"Passive meaning: (they were) frightened by the noise."}]},{id:"c1u11l2",title:"Shorter clauses",items:[{t:"mc",s:"The man ___ next to me on the train was reading my newspaper.",o:["sitting","sat","who sitting","was sitting"],a:0,x:"A reduced relative clause: the man (who was) sitting."},{t:"mc",s:"Most of the goods ___ in the factory are exported.",o:["produced","producing","are produced","having produced"],a:0,x:"Passive meaning: the goods (which are) produced."},{t:"type",s:"Anyone ___ (wish) to leave early should tell the teacher.",a:["wishing"],hint:"A reduced relative clause",x:"Anyone wishing = anyone who wishes."},{t:"spot",s:"Seeing from the air, the island looks like a heart.",wrong:0,fix:"Seen",x:"Passive meaning: (when it is) seen from the air."},{t:"kwt",s1:"After she had packed her bags, she called a taxi.",key:"HAVING",pre:"",post:"a taxi.",a:[["having packed her bags"],["she called"]],words:[3,6],x:"Having + past participle for the earlier action."},{t:"wf",s:"The film is ___ – I couldn't stop watching.",w:"GRIP",a:["gripping"],x:"-ing adjective: gripping = very exciting."},{t:"match",pairs:[["Having eaten,","after eating"],["Built in 1900,","which was built in 1900"],["Feeling tired,","because he felt tired"],["Walking home,","while walking home"]],x:"What each participle clause means."},{t:"mc",s:"___ the instructions carefully, you should have no problems.",o:["Following","Followed","Having been followed","To have followed"],a:0,x:"Following… = If you follow…"}]}]},{id:"c1u12",title:"Modals of deduction",part:"Part 4 · Modals",color:"violet",icon:"target",tips:["must have / can't have + past participle: certainty about the past.","may / might / could have: possibility.","should have / needn't have: criticism, and things that weren't necessary."],lessons:[{id:"c1u12l1",title:"Must have, can't have",items:[{t:"mc",s:"The streets are wet – it ___ in the night.",o:["must have rained","must rain","can't have rained","should rain"],a:0,x:"Certain about the past: must have + past participle."},{t:"mc",s:"She ___ the message – she hasn't replied.",o:["can't have read","mustn't have read","can't read","shouldn't have read"],a:0,x:"Sure it didn't happen: can't have + past participle."},{t:"kwt",s1:"I'm sure he forgot about our meeting.",key:"MUST",pre:"He",post:"about our meeting.",a:[["must have"],["forgotten"]],words:[3,6],x:"must have + past participle."},{t:"spot",s:"You must have saw the sign.",wrong:3,fix:"seen",x:"must have + past participle: seen."},{t:"type",s:"They ___ (might / take) the wrong road – they're very late.",a:["might have taken"],hint:"Possibility in the past",x:"might have + past participle."},{t:"mc",s:"He ___ been at the party – he was in Paris that night.",o:["can't have","must have","should have","needn't have"],a:0,x:"Impossible → can't have been."},{t:"tiles",pre:"The door is open. Someone",post:"it.",tiles:["must","have","opened","open","had"],a:["must","have","opened"],x:"A logical conclusion about the past."},{t:"kwt",s1:"It's possible that the letter was sent to the wrong address.",key:"MAY",pre:"The letter",post:"to the wrong address.",a:[["may have been"],["sent"]],words:[3,6],x:"Passive possibility: may have been + past participle."}]},{id:"c1u12l2",title:"Should have, needn't have",items:[{t:"mc",s:"You ___ told me you were coming – I would have cooked!",o:["should have","must have","can't have","would have"],a:0,x:"Criticism: should have + past participle."},{t:"mc",s:"I ___ taken an umbrella – it didn't rain in the end.",o:["needn't have","mustn't have","shouldn't","can't have"],a:0,x:"needn't have = I did it, but it wasn't necessary."},{t:"kwt",s1:"You brought a present, but it wasn't necessary.",key:"NEED",pre:"You",post:"a present.",a:[["need not have","needn't have"],["brought"]],words:[3,6],x:"need not have + past participle."},{t:"spot",s:"I should of called you earlier.",wrong:2,fix:"have",x:"should have – ‘of’ is only how it sounds."},{t:"type",s:"We ___ (not / should / leave) the window open – it's freezing.",a:["shouldn't have left","should not have left"],hint:"Criticism of a past action",x:"should not have + past participle."},{t:"mc",s:"Thanks for bringing food, but you ___ have – we'd already eaten.",o:["needn't","mustn't","can't","wouldn't"],a:0,x:"needn't have (brought it) – it wasn't necessary."},{t:"match",pairs:[["must have done","I'm sure it happened"],["can't have done","I'm sure it didn't happen"],["should have done","it was a good idea, but you didn't"],["needn't have done","you did it, but it wasn't necessary"]],x:"Past modals and what they mean."},{t:"tiles",pre:"You",post:"so rude to her.",tiles:["shouldn't","have","been","be","must"],a:["shouldn't","have","been"],x:"Criticism: shouldn't have been."}]}]},{id:"c1u13",title:"Ellipsis and substitution",part:"Part 2 · Grammar words",color:"blue",icon:"book",tips:["so and not replace a clause: I think so. I hope not.","one / ones replace a countable noun: the red one.","Leave out words that are obvious: I'd love to (go)."],lessons:[{id:"c1u13l1",title:"I hope so, I'm afraid not",items:[{t:"mc",s:"‘Will it rain tomorrow?’ ‘I hope ___.’",o:["not","no","don't","none"],a:0,x:"I hope not = I hope it won't."},{t:"mc",s:"‘Is she coming?’ ‘I think ___.’",o:["so","it","that","yes"],a:0,x:"I think so = I think she is."},{t:"type",s:"‘Did you pass?’ ‘I'm afraid ___.’",a:["not"],hint:"A negative reply",x:"I'm afraid not = unfortunately, no."},{t:"spot",s:"‘Do you like jazz?’ ‘Yes, I like.’",wrong:6,fix:"do",x:"Short answers use the auxiliary: Yes, I do."},{t:"type",s:"These shoes are too small. Have you got any bigger ___?",a:["ones"],hint:"It replaces shoes",x:"ones replaces a plural countable noun."},{t:"mc",s:"‘Would you like to join us?’ ‘I'd love ___.’",o:["to","it","so","that"],a:0,x:"I'd love to (join you)."},{t:"kwt",s1:"I haven't finished yet, and Tom hasn't finished either.",key:"NOR",pre:"I haven't finished yet,",post:"",a:[["and nor has","nor has"],["tom"]],words:[3,6],x:"nor + auxiliary + subject."},{t:"match",pairs:[["I think so.","yes, probably"],["I hope not.","I don't want it to happen"],["I'm afraid so.","yes, unfortunately"],["I doubt it.","probably not"]],x:"Short replies and what they mean."}]},{id:"c1u13l2",title:"Leaving words out",items:[{t:"mc",s:"She said she'd call, but she ___.",o:["didn't","didn't call it","hasn't","wasn't"],a:0,x:"didn't (call) – the verb is understood."},{t:"mc",s:"I've never been to Japan, but my sister ___.",o:["has","is","was","does"],a:0,x:"has (been to Japan)."},{t:"type",s:"He can speak Chinese, and ___ can his wife.",a:["so"],hint:"Agreeing with a positive",x:"so + auxiliary + subject."},{t:"spot",s:"I don't like horror films, and my brother does either.",wrong:8,fix:"doesn't",x:"Negative agreement: my brother doesn't either."},{t:"kwt",s1:"Anna wasn't at the meeting, and Paul wasn't there either.",key:"NEITHER",pre:"Anna wasn't at the meeting, and",post:"",a:[["neither was"],["paul"]],words:[3,6],x:"neither + auxiliary + subject."},{t:"mc",s:"I prefer the blue shirt to the ___ you're wearing.",o:["one","it","that one it","ones"],a:0,x:"one replaces a singular countable noun."},{t:"wf",s:"The report was ___ – it left out several key facts.",w:"COMPLETE",a:["incomplete"],x:"Negative prefix: incomplete."},{t:"mc",s:"‘You should apologise.’ ‘I know I ___.’",o:["should","should apologise it","do","am"],a:0,x:"I know I should (apologise)."}]}]},{id:"c1u14",title:"Key verb collocations",part:"Part 1 · Collocations",color:"green",icon:"star",tips:["come to a decision, come into force, come under criticism.","bring about change, bring to an end, bring up a subject.","take into account, take for granted, take advantage of."],lessons:[{id:"c1u14l1",title:"Come and bring",items:[{t:"mc",s:"After hours of discussion, the committee finally ___ to a decision.",o:["came","arrived","made","took"],a:0,x:"come to a decision. (arrive at, make or take a decision – without to.)"},{t:"mc",s:"The new law will ___ into force next month.",o:["come","go","bring","get"],a:0,x:"come into force = start to apply."},{t:"type",s:"The minister has ___ under heavy criticism for the decision.",a:["come"],hint:"The past participle",x:"come under criticism."},{t:"mc",s:"The war was finally ___ to an end in 1945.",o:["brought","come","put","taken"],a:0,x:"bring something to an end."},{t:"spot",s:"The internet has brought on huge changes in the way we work.",wrong:4,fix:"about",x:"bring about change = cause it. (bring on is used for illnesses.)"},{t:"kwt",s1:"Nobody mentioned the subject of money at the meeting.",key:"BROUGHT",pre:"The subject of money",post:"at the meeting.",a:[["was not brought","wasn't brought"],["up"]],words:[3,6],x:"Passive of bring up (= mention)."},{t:"match",pairs:[["come to","a conclusion"],["come into","force"],["bring about","change"],["bring up","a subject"]],x:"Collocations with come and bring."},{t:"wf",s:"The ___ of the new rules caused confusion.",w:"INTRODUCE",a:["introduction"],x:"Noun after the: introduction."}]},{id:"c1u14l2",title:"Take and make",items:[{t:"mc",s:"The judges will ___ into account the age of the students.",o:["take","bring","make","put"],a:0,x:"take something into account."},{t:"mc",s:"We tend to take clean water for ___.",o:["granted","given","sure","certain"],a:0,x:"take something for granted."},{t:"type",s:"She took full ___ of the opportunity to travel.",a:["advantage"],hint:"take … of",x:"take advantage of."},{t:"kwt",s1:"Please consider the cost when you make your decision.",key:"ACCOUNT",pre:"Please",post:"when you make your decision.",a:[["take the cost into"],["account"]],words:[3,6],x:"take something into account = consider it."},{t:"spot",s:"The company did a large profit last year.",wrong:2,fix:"made",x:"make a profit / a loss."},{t:"mc",s:"It ___ no difference to me whether we go today or tomorrow.",o:["makes","does","takes","gives"],a:0,x:"make no difference."},{t:"tiles",pre:"Don't",post:"for granted.",tiles:["take","your","health","make","it"],a:["take","your","health"],x:"take something for granted."},{t:"match",pairs:[["take into account","consider"],["make allowances for","be tolerant of"],["take for granted","fail to appreciate"],["make the most of","use fully"]],x:"Phrases and their meanings."}]}]},{id:"c1u15",title:"Reporting verbs",part:"Part 4 · Reporting",color:"amber",icon:"doc",tips:["verb + to: agree, offer, refuse, threaten, promise.","verb + object + to: advise, persuade, urge, warn, encourage.","verb + -ing or a preposition: admit, deny, suggest; accuse of, blame for, apologise for, insist on."],lessons:[{id:"c1u15l1",title:"Offer, deny, threaten",items:[{t:"mc",s:"He ___ to lend me his car.",o:["offered","suggested","insisted","admitted"],a:0,x:"offer + to do."},{t:"mc",s:"She denied ___ the money.",o:["taking","to take","take","that take"],a:0,x:"deny + -ing."},{t:"kwt",s1:"‘I'll call the police if you don't leave,’ he said to them.",key:"THREATENED",pre:"He",post:"the police if they didn't leave.",a:[["threatened"],["to call"]],words:[3,6],x:"threaten + to do."},{t:"spot",s:"He admitted to steal the money.",wrong:3,fix:"stealing",x:"admit (to) + -ing."},{t:"type",s:"My friends persuaded me ___ (enter) the competition.",a:["to enter"],hint:"persuade somebody + ?",x:"persuade somebody to do something."},{t:"mc",s:"The teacher accused him ___ cheating.",o:["of","for","with","about"],a:0,x:"accuse somebody of something."},{t:"kwt",s1:"‘It was my fault that we lost,’ said the captain.",key:"BLAMED",pre:"The captain",post:"the defeat.",a:[["blamed himself"],["for"]],words:[3,6],x:"blame somebody for something."},{t:"match",pairs:[["refuse","+ to do"],["advise","+ somebody to do"],["deny","+ -ing"],["insist","+ on -ing"]],x:"Reporting verbs and their patterns."}]},{id:"c1u15l2",title:"Warn, urge, apologise",items:[{t:"mc",s:"The doctor ___ me to cut down on sugar.",o:["advised","suggested","insisted","recommended to"],a:0,x:"advise somebody to do something."},{t:"mc",s:"They apologised ___ the delay.",o:["for","of","about","with"],a:0,x:"apologise for something."},{t:"kwt",s1:"‘Don't swim here – it's dangerous,’ the lifeguard told us.",key:"WARNED",pre:"The lifeguard",post:"there because it was dangerous.",a:[["warned us not"],["to swim"]],words:[3,6],x:"warn somebody not to do something."},{t:"spot",s:"She insisted on pay for the meal.",wrong:3,fix:"paying",x:"insist on + -ing."},{t:"type",s:"The manager congratulated her ___ winning the award.",a:["on"],hint:"A preposition",x:"congratulate somebody on something."},{t:"mc",s:"He ___ that we should leave early.",o:["suggested","persuaded","encouraged","offered"],a:0,x:"suggest that + clause."},{t:"kwt",s1:"‘You really must visit the museum,’ Maria said to us.",key:"URGED",pre:"Maria",post:"the museum.",a:[["urged us"],["to visit","to go to"]],words:[3,6],x:"urge somebody to do something."},{t:"tiles",pre:"She",post:"for being late.",tiles:["apologised","to","me","apologies","sorry"],a:["apologised","to","me"],x:"apologise to somebody for something."}]}]},{id:"c1u16",title:"Formal and informal",part:"Writing · Register",color:"pink",icon:"pen",tips:["Formal: longer, Latin-based words – obtain, require, assist, commence.","Informal: phrasal verbs, contractions and direct questions – get, need, help, start.","Choose the register for your reader: a proposal to a principal is formal; an email to a friend is not."],lessons:[{id:"c1u16l1",title:"Formal equivalents",items:[{t:"mc",s:"(formal for ‘got’) We ___ your letter on 3 May.",o:["received","got","took","picked up"],a:0,x:"receive is the formal choice."},{t:"mc",s:"(formal for ‘find out’) We need to ___ the cause of the problem.",o:["ascertain","figure","sort","dig"],a:0,x:"ascertain = find out (formal)."},{t:"type",s:"(formal for ‘ask for’) I am writing to ___ information about the course.",a:["request"],hint:"A formal verb",x:"request = ask for (formal)."},{t:"match",pairs:[["start","commence"],["help","assist"],["need","require"],["buy","purchase"]],x:"Everyday words and their formal equivalents."},{t:"spot",s:"I am writing to complain about the awful service I got.",wrong:10,fix:"received",x:"In a formal letter, received sounds more appropriate than got."},{t:"mc",s:"Which is most appropriate in a formal proposal?",o:["It is recommended that the library opens later.","I reckon the library should open later.","Why not open the library later?","The library's got to open later."],a:0,x:"Impersonal passive – typical of proposals and reports."},{t:"wf",s:"I would be ___ if you could send me further details.",w:"GRATITUDE",a:["grateful"],x:"Adjective after would be: grateful."},{t:"mc",s:"(formal for ‘put off’) The meeting has been ___.",o:["postponed","delayed off","put back off","stopped"],a:0,x:"postpone = put off (formal)."}]},{id:"c1u16l2",title:"Knowing your reader",items:[{t:"mc",s:"Which opening suits an email to a close friend?",o:["Hi Sam, great to hear from you!","Dear Sir or Madam,","To whom it may concern,","Dear Mr Smith,"],a:0,x:"Informal greeting for a friend."},{t:"mc",s:"Which closing suits a letter that begins ‘Dear Sir or Madam’?",o:["Yours faithfully,","Yours sincerely,","Love,","Cheers,"],a:0,x:"Dear Sir or Madam → Yours faithfully."},{t:"type",s:"‘Dear Ms Patel’ is usually closed with ‘Yours ___’.",a:["sincerely"],hint:"A formal closing when you know the name",x:"Dear + name → Yours sincerely."},{t:"spot",s:"Dear Sir or Madam, I'm gonna explain why I am applying.",wrong:5,fix:"going to",x:"gonna is far too informal for a letter of application."},{t:"match",pairs:[["Furthermore,","What's more,"],["Nevertheless,","Still,"],["Consequently,","So,"],["Regarding","About"]],x:"Formal linkers and their informal equivalents."},{t:"mc",s:"In a report, which heading is most appropriate?",o:["Recommendations","What I think you should do","Some ideas!","OK, so…"],a:0,x:"Reports use short, neutral headings."},{t:"kwt",s1:"You must book in advance.",key:"REQUIRED",pre:"Visitors",post:"in advance.",a:[["are required"],["to book"]],words:[3,6],x:"Formal passive: are required to do something."},{t:"wf",s:"Please accept my ___ for the inconvenience.",w:"APOLOGISE",a:["apologies"],x:"Plural noun: accept my apologies."}]}]},{id:"c1u17",title:"Easily confused words",part:"Part 1 · Confusables",color:"red",icon:"heart",tips:["affect (verb) / effect (noun); principal / principle; stationary / stationery.","raise (+ object) / rise (no object); lay (+ object) / lie.","economic (about the economy) / economical (saving money)."],lessons:[{id:"c1u17l1",title:"Affect or effect?",items:[{t:"mc",s:"The weather can ___ your mood.",o:["affect","effect","infect","afflict"],a:0,x:"affect is the verb."},{t:"mc",s:"The new policy had little ___ on unemployment.",o:["effect","affect","effort","efficiency"],a:0,x:"effect is the noun: have an effect on."},{t:"mc",s:"The government plans to ___ taxes next year.",o:["raise","rise","arise","rouse"],a:0,x:"raise + object; rise has no object."},{t:"spot",s:"Prices have raised sharply this year.",wrong:2,fix:"risen",x:"No object → rise, risen."},{t:"type",s:"This car is very ___ (economy) – it uses little fuel.",a:["economical"],hint:"Saving money",x:"economical = not wasting money or fuel."},{t:"mc",s:"She ___ down on the sofa and fell asleep.",o:["lay","laid","lied","layed"],a:0,x:"lie (down) – lay – lain."},{t:"match",pairs:[["principal","most important"],["principle","a basic rule"],["stationary","not moving"],["stationery","paper and pens"]],x:"Words that sound alike."},{t:"wf",s:"The country's ___ problems include high inflation.",w:"ECONOMY",a:["economic"],x:"economic = connected with the economy."}]},{id:"c1u17l2",title:"Similar but different",items:[{t:"mc",s:"I'd like some ___ on which course to choose.",o:["advice","advise","advices","advising"],a:0,x:"advice (noun, uncountable); advise (verb)."},{t:"mc",s:"She ___ me of my mother.",o:["reminds","remembers","recalls","memorises"],a:0,x:"remind somebody of somebody."},{t:"mc",s:"The ___ of the novel is a young woman in 1920s Paris.",o:["protagonist","antagonist","prologue","protocol"],a:0,x:"protagonist = the main character."},{t:"spot",s:"He was so exciting about the trip that he couldn't sleep.",wrong:3,fix:"excited",x:"His feeling → excited."},{t:"type",s:"Could you ___ (lend / borrow) me your pen?",a:["lend"],hint:"Give for a short time",x:"lend = give; borrow = take."},{t:"mc",s:"The museum is ___ to the public on Mondays.",o:["closed","shut down","closing","enclosed"],a:0,x:"closed to the public."},{t:"kwt",s1:"The medicine didn't help her at all.",key:"EFFECT",pre:"The medicine",post:"on her at all.",a:[["had no"],["effect"]],words:[3,6],x:"have no effect on somebody."},{t:"match",pairs:[["sensible","practical and wise"],["sensitive","easily upset"],["historic","important in history"],["historical","about the past"]],x:"Pairs that are easy to mix up."}]}]},{id:"c1u18",title:"Abstract nouns",part:"Part 3 · Noun formation",color:"violet",icon:"pen",tips:["-ance / -ence: tolerance, reliance, confidence, existence.","-ity / -ty, -ship, -hood: ability, loyalty, leadership, childhood.","Watch spelling changes: deep → depth, strong → strength, proud → pride."],lessons:[{id:"c1u18l1",title:"From adjective to noun",items:[{t:"wf",s:"The ___ of the lake surprised the divers.",w:"DEEP",a:["depth"],x:"deep → depth."},{t:"wf",s:"Her ___ to detail is remarkable.",w:"ATTEND",a:["attention"],x:"attention to detail."},{t:"mc",s:"We were impressed by his ___ to stay calm.",o:["ability","able","ably","abilities"],a:0,x:"A noun after his: ability to do something."},{t:"wf",s:"There is no ___ that the plan will work.",w:"CERTAIN",a:["certainty"],x:"certain → certainty."},{t:"spot",s:"She spoke with great confident about her future.",wrong:4,fix:"confidence",x:"A noun after great: confidence."},{t:"wf",s:"His ___ to his friends is admirable.",w:"LOYAL",a:["loyalty"],x:"loyal → loyalty."},{t:"match",pairs:[["strong","strength"],["proud","pride"],["wide","width"],["true","truth"]],x:"Adjectives and their nouns."},{t:"type",s:"Those ___ (child) memories stayed with her for ever.",a:["childhood"],hint:"A noun with -hood",x:"childhood memories."}]},{id:"c1u18l2",title:"From verb to noun",items:[{t:"wf",s:"The ___ of the new stadium took three years.",w:"CONSTRUCT",a:["construction"],x:"construct → construction."},{t:"wf",s:"There has been a sharp ___ in the number of visitors.",w:"REDUCE",a:["reduction"],x:"reduce → reduction."},{t:"wf",s:"Her ___ on her parents worried her teachers.",w:"RELY",a:["reliance"],x:"rely → reliance on."},{t:"mc",s:"The ___ of the meeting is to agree a budget.",o:["purpose","purposely","purposeful","purposing"],a:0,x:"A noun after the: purpose."},{t:"spot",s:"The approve of the committee is required.",wrong:1,fix:"approval",x:"A noun after the: approval."},{t:"wf",s:"The ___ of the painting was confirmed by experts.",w:"AUTHENTIC",a:["authenticity"],x:"authentic → authenticity."},{t:"kwt",s1:"The public reacted angrily to the announcement.",key:"REACTION",pre:"The public's",post:"angry.",a:[["reaction to the"],["announcement was"]],words:[3,6],x:"Verb → noun: the public's reaction to… was angry."},{t:"match",pairs:[["refuse","refusal"],["arrive","arrival"],["deny","denial"],["survive","survival"]],x:"Verbs with -al nouns."}]}]},{id:"c1u19",title:"Hardly, barely, whatsoever",part:"Part 2 · Emphasis",color:"amber",icon:"bolt",tips:["hardly / barely / scarcely = almost not: I could hardly breathe.","at all, whatsoever and in the slightest make negatives stronger.","such / so, what a…, the very…: emphasis in speech and writing."],lessons:[{id:"c1u19l1",title:"Hardly any",items:[{t:"mc",s:"There's ___ any milk left – can you buy some?",o:["hardly","hard","barely no","scarce"],a:0,x:"hardly any = almost no."},{t:"mc",s:"I had ___ sat down when the phone rang.",o:["barely","bare","barley","barest"],a:0,x:"had barely done… when…"},{t:"type",s:"I have no interest ___ in football.",a:["whatsoever","at all"],hint:"Makes the negative stronger",x:"no interest whatsoever / at all."},{t:"spot",s:"I could hard believe my eyes.",wrong:2,fix:"hardly",x:"hard = with effort; hardly = almost not."},{t:"kwt",s1:"I didn't enjoy the film at all.",key:"SLIGHTEST",pre:"I didn't enjoy the film",post:"",a:[["in the"],["slightest"]],words:[3,6],x:"not … in the slightest = not at all."},{t:"mc",s:"She's ___ a talented singer that she's already famous.",o:["such","so","very","too"],a:0,x:"such + a + adjective + noun + that."},{t:"tiles",pre:"There was",post:"left to eat.",tiles:["hardly","anything","nothing","hard"],a:["hardly","anything"],x:"hardly anything = almost nothing."},{t:"match",pairs:[["hardly ever","almost never"],["hardly anyone","almost nobody"],["hardly anything","almost nothing"],["hardly anywhere","almost nowhere"]],x:"hardly + any- / ever."}]},{id:"c1u19l2",title:"The very best",items:[{t:"mc",s:"This is the ___ book I was looking for!",o:["very","real","much","so"],a:0,x:"the very = exactly this one."},{t:"mc",s:"___ a beautiful view!",o:["What","How","Such","So"],a:0,x:"What + a + adjective + noun!"},{t:"type",s:"He's by ___ the best player in the team.",a:["far"],hint:"Emphasis with a superlative",x:"by far the best."},{t:"spot",s:"It was so a good film that we watched it twice.",wrong:2,fix:"such",x:"such a + adjective + noun."},{t:"kwt",s1:"I had no idea that she was ill.",key:"LEAST",pre:"I didn't have",post:"that she was ill.",a:[["the least"],["idea"]],words:[3,6],x:"not have the least idea = have no idea at all."},{t:"mc",s:"Not ___ person came to the meeting.",o:["a single","any","no","one single of"],a:0,x:"Not a single… = nobody at all."},{t:"wf",s:"The results were ___ good – better than anyone had hoped.",w:"EXCEPTION",a:["exceptionally"],x:"Adverb before an adjective: exceptionally good."},{t:"mc",s:"I'm ___ tired I can't think.",o:["so","such","too","very"],a:0,x:"so + adjective + (that)."}]}]},{id:"c1u20",title:"Phrasal verbs for discussion",part:"Part 1 · Phrasal verbs",color:"blue",icon:"chart",tips:["put forward / come up with an idea; point out a problem; back up a claim.","rule out = decide something isn't possible; go along with = accept.","Many have a formal one-word equivalent: put forward = propose."],lessons:[{id:"c1u20l1",title:"Ideas and arguments",items:[{t:"mc",s:"Several solutions were put ___ at the meeting.",o:["forward","across","off","up with"],a:0,x:"put forward = propose."},{t:"mc",s:"She pointed ___ that the figures were out of date.",o:["out","up","at","over"],a:0,x:"point out = mention something important."},{t:"type",s:"Can you back ___ your claim with evidence?",a:["up"],hint:"A particle",x:"back up = support."},{t:"spot",s:"Police have ruled off the possibility of a crime.",wrong:3,fix:"out",x:"rule out = decide something isn't possible."},{t:"kwt",s1:"Who first suggested this idea?",key:"CAME",pre:"Who",post:"this idea first?",a:[["came up"],["with"]],words:[3,6],x:"come up with = think of an idea."},{t:"mc",s:"I don't agree, but I'll go ___ with your plan.",o:["along","ahead","over","through"],a:0,x:"go along with = accept."},{t:"match",pairs:[["put forward","propose"],["rule out","exclude"],["back up","support"],["point out","mention"]],x:"Phrasal verbs and formal equivalents."},{t:"wf",s:"The ___ was rejected by the council.",w:"PROPOSE",a:["proposal"],x:"propose → proposal."}]},{id:"c1u20l2",title:"Reaching a decision",items:[{t:"mc",s:"After a long debate, they finally came ___ to our point of view.",o:["round","off","through","up"],a:0,x:"come round to = finally accept."},{t:"mc",s:"Let's not rush into anything – I need time to think it ___.",o:["over","up","off","in"],a:0,x:"think something over = consider it carefully."},{t:"type",s:"The deal fell ___ at the last minute.",a:["through"],hint:"Failed to happen",x:"fall through = fail to happen."},{t:"spot",s:"We need to sort out the details before we carry on the plan.",wrong:10,fix:"out",x:"carry out a plan = do it. (carry on = continue.)"},{t:"kwt",s1:"They postponed the meeting until next week.",key:"OFF",pre:"The meeting",post:"until next week.",a:[["was put"],["off"]],words:[3,6],x:"Passive of put off (= postpone)."},{t:"mc",s:"The two sides were unable to ___ out their differences.",o:["iron","press","clear","flatten"],a:0,x:"iron out = solve small problems."},{t:"match",pairs:[["fall through","fail to happen"],["iron out","resolve"],["think over","consider"],["come round to","accept in the end"]],x:"Phrasal verbs for decisions."},{t:"tiles",pre:"We'll have to",post:"the plan until we have more money.",tiles:["put","off","out","on","away"],a:["put","off"],x:"put off = postpone."}]}]}),LZ.data.guide=LZ.data.guide||{},Object.assign(LZ.data.guide,{c1u11:{idea:"Participle clauses make writing shorter and more sophisticated: they replace a whole clause with an -ing form, having + past participle or a past participle.",rules:[["Same time / reason","Feeling tired, she went to bed."],["Earlier action","Having finished, he left."],["Passive meaning","Built in 1900, the house needs repairs."]],trap:["Walking into the room, the lights went out.","Walking into the room, I saw the lights go out.","The subject of both clauses must be the same."],exam:"Part 4 transformations often turn ‘Because…’ or ‘After…’ into a participle clause – and it lifts your Writing mark for range."},c1u12:{idea:"Modal + have + past participle lets you draw conclusions, speculate and criticise – all about the past.",rules:[["Certain","must have / can't have + past participle"],["Possible","may / might / could have + past participle"],["Criticism / unnecessary","should have, shouldn't have, needn't have"]],trap:["You mustn't have seen me.","You can't have seen me.","The opposite of must have is can't have."],exam:"Part 4 regularly tests these – ‘I'm sure…’ becomes must have, ‘It's possible that…’ becomes may have."},c1u13:{idea:"Good writers don't repeat themselves. They replace words with so, not, one or an auxiliary – or leave them out altogether.",rules:[["Replacing a clause","I think so. I'm afraid not."],["Replacing a noun","the blue one, the ones on the left"],["Leaving words out","She said she'd call, but she didn't."]],trap:["‘Do you like it?’ ‘Yes, I like.’","‘Do you like it?’ ‘Yes, I do.’","Short answers use the auxiliary."],exam:"Part 2 often tests so, nor, neither and one – read the sentence before the gap."},c1u14:{idea:"Common verbs combine with nouns in fixed ways. At C1, the exam tests the less obvious ones.",rules:[["come","to a decision, into force, under criticism"],["bring","about change, to an end, up a subject"],["take / make","into account, for granted; the most of, allowances for"]],trap:["The company did a profit.","The company made a profit.","make a profit / a loss."],exam:"Part 1 gives four verbs that look possible – only one forms the fixed phrase."},c1u15:{idea:"Reporting verbs summarise what someone said – and each one has its own pattern.",rules:[["+ to","agree, offer, refuse, threaten, promise"],["+ object + to","advise, persuade, urge, warn, encourage"],["+ -ing / preposition","deny, admit, suggest; accuse of, blame for, insist on"]],trap:["She suggested me to go.","She suggested (that) I (should) go.","suggest never takes object + to."],exam:"Part 4 often turns direct speech into a reporting verb: ‘Don't…’ → warned somebody not to…"},c1u16:{idea:"Register is choosing the right level of formality for your reader. Getting it wrong costs marks for Communicative Achievement.",rules:[["Formal vocabulary","obtain, require, assist, commence"],["Formal structures","It is recommended that…; passive voice"],["Informal features","contractions, phrasal verbs, direct questions"]],trap:["Dear Sir or Madam, I wanna apply for the job.","Dear Sir or Madam, I would like to apply for the position.","Match the register to the opening."],exam:"C1 Writing Part 2 includes proposals, reports and letters – each has its own expected register."},c1u17:{idea:"Some words look or sound alike but mean different things. The exam loves them.",rules:[["affect / effect","It affects me. It has an effect on me."],["raise / rise","raise prices (+ object); prices rise"],["economic / economical","economic growth; an economical car"]],trap:["Prices have raised.","Prices have risen.","rise has no object."],exam:"Part 1 options are often confusable pairs – check the grammar around the gap, not just the meaning."},c1u18:{idea:"Abstract nouns name ideas and qualities. Part 3 of the exam is full of them, often with spelling changes.",rules:[["-ance / -ence","reliance, tolerance, confidence"],["-ity / -ty / -ship / -hood","ability, loyalty, leadership, childhood"],["Irregular","deep → depth, strong → strength, proud → pride"]],trap:["She spoke with great confident.","She spoke with great confidence.","After an adjective like great, you need a noun."],exam:"In Part 3, look at the word before the gap: after the, a, his or great you usually need a noun."},c1u19:{idea:"Emphasis makes writing and speaking more expressive – and C1 examiners reward it.",rules:[["Almost not","hardly, barely, scarcely (+ any / ever)"],["Stronger negatives","at all, whatsoever, in the slightest"],["Emphasis","such a…, so…, what a…, the very…, by far"]],trap:["It was so a good film.","It was such a good film.","such + a + adjective + noun; so + adjective."],exam:"Part 2 often gaps the small word in these phrases: by far, at all, in the slightest."},c1u20:{idea:"Discussions and arguments are full of phrasal verbs – especially in Speaking Part 3 and in essays.",rules:[["Ideas","put forward, come up with, point out, back up"],["Deciding","rule out, go along with, come round to, think over"],["Plans","carry out, put off, fall through, iron out"]],trap:["We need to carry on the plan.","We need to carry out the plan.","carry out = do; carry on = continue."],exam:"Speaking Part 3: ‘Could I just point out…’, ‘Shall we rule that one out?’ – they make the discussion sound natural."}});
